#!/usr/bin/env python3
"""Foreground supervisor: runs redis (miniredis), 3 HTTP nodes and the IRC gateway; respawns any that die."""
import os
import signal
import subprocess
import sys
import time

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, ROOT)
os.chdir(ROOT)

from huddle import config  # noqa: E402

PY = sys.executable or "python3"


def specs():
    s = [("redis", [PY, os.path.join(ROOT, "bin", "redis-server"), "--port", str(config.REDIS_PORT)])]
    for i in range(config.NUM_NODES):
        s.append((f"node{i}", [PY, "-m", "huddle.node", "--node-id", str(i)]))
    s.append(("irc", [PY, "-m", "huddle.irc"]))
    return s


def main():
    os.makedirs(config.DATA_DIR, exist_ok=True)
    log_dir = os.path.join(config.DATA_DIR, "logs")
    os.makedirs(log_dir, exist_ok=True)
    env = dict(os.environ, PYTHONPATH=ROOT, PYTHONUNBUFFERED="1")
    procs = {}
    stopping = False

    def spawn(name, cmd):
        log = open(os.path.join(log_dir, f"{name}.log"), "ab")
        p = subprocess.Popen(cmd, cwd=ROOT, env=env, stdout=log, stderr=subprocess.STDOUT)
        log.close()
        procs[name] = (p, cmd, time.time())
        print(f"[supervisor] started {name} pid={p.pid}", flush=True)

    def shutdown(*_):
        nonlocal stopping
        stopping = True
        for p, _, _ in procs.values():
            try:
                p.terminate()
            except Exception:
                pass
        deadline = time.time() + 3
        for p, _, _ in procs.values():
            try:
                p.wait(max(0.1, deadline - time.time()))
            except Exception:
                try:
                    p.kill()
                except Exception:
                    pass
        sys.exit(0)

    signal.signal(signal.SIGTERM, shutdown)
    signal.signal(signal.SIGINT, shutdown)

    for name, cmd in specs():
        spawn(name, cmd)
        if name == "redis":
            time.sleep(0.3)

    while not stopping:
        time.sleep(0.25)
        for name, (p, cmd, started) in list(procs.items()):
            if p.poll() is not None:
                print(f"[supervisor] {name} exited rc={p.returncode}; respawning", flush=True)
                # brief backoff if it is crash-looping
                if time.time() - started < 2:
                    time.sleep(0.5)
                spawn(name, cmd)


if __name__ == "__main__":
    main()

"""HTTP plumbing shared by the node server and the API (see CONTRACTS.md)."""
import json as _json


class Request:
    def __init__(self, method="GET", path="/", query=None, headers=None, body=b"", node_id=0):
        self.method = method.upper()
        self.path = path
        self.query = query or {}
        self.headers = {k.lower(): v for k, v in (headers or {}).items()}
        self.body = body or b""
        self.node_id = node_id

    def json(self):
        if not self.body:
            return {}
        try:
            return _json.loads(self.body.decode("utf-8"))
        except Exception as e:
            raise ValueError(f"invalid JSON: {e}")


class Response:
    def __init__(self, status=200, body=None, headers=None, content_type=None):
        self.status = status
        self.headers = dict(headers or {})
        if isinstance(body, (dict, list)):
            self.body = _json.dumps(body, separators=(",", ":")).encode("utf-8")
            self.content_type = content_type or "application/json"
        elif isinstance(body, str):
            self.body = body.encode("utf-8")
            self.content_type = content_type or "text/plain; charset=utf-8"
        elif isinstance(body, (bytes, bytearray)):
            self.body = bytes(body)
            self.content_type = content_type or "application/octet-stream"
        else:
            self.body = b""
            self.content_type = content_type

"""Durable channel events + cluster fan-out (see CONTRACTS.md).

append()   -> inside the caller's BEGIN IMMEDIATE transaction, allocates the dense per-channel seq.
publish()  -> after COMMIT; non-blocking, never raises. Delivers locally (if this process is an
              HTTP node) and PUBLISHes to the local redis on channel `huddle:events` from a
              background thread. Every node also tails `channel_events` / `global_events` in sqlite,
              so delivery continues even while redis is down.
"""
import json
import os
import queue
import socket
import threading
import time
import uuid
from datetime import datetime, timezone

from huddle import config

REDIS_CHANNEL = "huddle:events"
PRESENCE_TTL = 6.0

# set by huddle.node: callable(kind, frame) invoked from any thread; must be thread-safe & fast.
_local_hook = None
# set by huddle.node: callable() -> set[int] of users connected to this process, and node id.
_local_online = None
_local_node_id = None


def _now_iso():
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%f")[:-3] + "Z"


_SCHEMA = """
CREATE TABLE IF NOT EXISTS channel_events(
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    channel_id INTEGER NOT NULL,
    seq INTEGER NOT NULL,
    type TEXT NOT NULL,
    payload TEXT NOT NULL,
    created_at TEXT NOT NULL,
    UNIQUE(channel_id, seq)
);
CREATE TABLE IF NOT EXISTS global_events(
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    uid TEXT NOT NULL,
    payload TEXT NOT NULL,
    created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS ws_presence(
    node_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    conn_count INTEGER NOT NULL,
    updated_at REAL NOT NULL,
    PRIMARY KEY(node_id, user_id)
);
"""

_schema_done = False
_schema_lock = threading.Lock()


def ensure_schema(conn) -> None:
    global _schema_done
    if _schema_done:
        return
    with _schema_lock:
        if _schema_done:
            return
        for stmt in _SCHEMA.split(";"):
            if stmt.strip():
                for _ in range(50):
                    try:
                        conn.execute(stmt)
                        break
                    except Exception as e:  # "database is locked" during concurrent startup
                        if "locked" not in str(e):
                            raise
                        time.sleep(0.05)
        _schema_done = True


def append(conn, channel_id: int, kind: str, data: dict) -> dict:
    """Must be called inside a transaction opened with BEGIN IMMEDIATE."""
    ensure_schema(conn)
    channel_id = int(channel_id)
    row = conn.execute(
        "SELECT COALESCE(MAX(seq), 0) + 1 FROM channel_events WHERE channel_id=?", (channel_id,)
    ).fetchone()
    seq = int(row[0])
    frame = {"type": kind, "seq": seq, "channel_id": channel_id}
    for k, v in (data or {}).items():
        if k not in ("type", "seq", "channel_id"):
            frame[k] = v
    conn.execute(
        "INSERT INTO channel_events(channel_id, seq, type, payload, created_at) VALUES(?,?,?,?,?)",
        (channel_id, seq, kind, json.dumps(frame, separators=(",", ":")), _now_iso()),
    )
    return frame


def head_seq(conn, channel_id: int) -> int:
    ensure_schema(conn)
    row = conn.execute(
        "SELECT COALESCE(MAX(seq), 0) FROM channel_events WHERE channel_id=?", (int(channel_id),)
    ).fetchone()
    return int(row[0])


# ---------------------------------------------------------------------------------------------
# publishing

class _Publisher(threading.Thread):
    """Background thread: writes global events to sqlite and PUBLISHes everything to redis."""

    def __init__(self):
        super().__init__(name="huddle-redis-publisher", daemon=True)
        self.q = queue.Queue(maxsize=100000)
        self.sock = None
        self.next_try = 0.0
        self.db = None

    def put(self, item):
        try:
            self.q.put_nowait(item)
        except queue.Full:
            pass

    def _connect(self):
        if self.sock is not None:
            return True
        now = time.time()
        if now < self.next_try:
            return False
        try:
            s = socket.create_connection((config.HOST, config.REDIS_PORT), timeout=0.5)
            s.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
            s.settimeout(2.0)
            self.sock = s
            return True
        except Exception:
            self.next_try = now + 0.5
            return False

    def _drop(self):
        try:
            if self.sock:
                self.sock.close()
        except Exception:
            pass
        self.sock = None
        self.next_try = time.time() + 0.3

    def _db(self):
        if self.db is None:
            self.db = config.connect()
            ensure_schema(self.db)
        return self.db

    def _store_global(self, uid, frame):
        for _ in range(3):
            try:
                db = self._db()
                db.execute(
                    "INSERT INTO global_events(uid, payload, created_at) VALUES(?,?,?)",
                    (uid, json.dumps(frame, separators=(",", ":")), _now_iso()),
                )
                return
            except Exception:
                try:
                    self.db.close()
                except Exception:
                    pass
                self.db = None
                time.sleep(0.05)

    def run(self):
        while True:
            items = [self.q.get()]
            try:
                while len(items) < 500:
                    items.append(self.q.get_nowait())
            except queue.Empty:
                pass
            msgs = []
            for kind, frame, uid in items:
                if kind == "g":
                    self._store_global(uid, frame)
                    msgs.append(json.dumps({"g": uid, "f": frame}, separators=(",", ":")))
                else:
                    msgs.append(json.dumps({"f": frame}, separators=(",", ":")))
            if not self._connect():
                continue  # redis down: the sqlite tail on every node covers delivery
            try:
                out = bytearray()
                ch = REDIS_CHANNEL.encode()
                for m in msgs:
                    b = m.encode("utf-8")
                    out += b"*3\r\n$7\r\nPUBLISH\r\n$%d\r\n%s\r\n$%d\r\n%s\r\n" % (len(ch), ch, len(b), b)
                self.sock.sendall(out)
                # consume the integer replies (":N\r\n" each)
                need = len(msgs)
                buf = b""
                while need > 0:
                    chunk = self.sock.recv(65536)
                    if not chunk:
                        raise ConnectionError("redis closed")
                    buf += chunk
                    n = buf.count(b"\r\n")
                    if n >= need:
                        break
            except Exception:
                self._drop()


_pub = None
_pub_lock = threading.Lock()


def _publisher():
    global _pub
    if _pub is None:
        with _pub_lock:
            if _pub is None:
                p = _Publisher()
                p.start()
                _pub = p
    return _pub


def publish(frame: dict) -> None:
    try:
        hook = _local_hook
        if hook is not None:
            try:
                hook("c", frame, None)
            except Exception:
                pass
        _publisher().put(("c", frame, None))
    except Exception:
        pass


def publish_global(frame: dict) -> None:
    try:
        uid = uuid.uuid4().hex
        hook = _local_hook
        if hook is not None:
            try:
                hook("g", frame, uid)
            except Exception:
                pass
        _publisher().put(("g", frame, uid))
    except Exception:
        pass


# ---------------------------------------------------------------------------------------------
# presence

_presence_db = threading.local()


def online_user_ids() -> set:
    users = set()
    try:
        if _local_online is not None:
            users |= set(_local_online())
    except Exception:
        pass
    try:
        db = getattr(_presence_db, "conn", None)
        if db is None:
            db = config.connect()
            ensure_schema(db)
            _presence_db.conn = db
        cutoff = time.time() - PRESENCE_TTL
        if _local_node_id is not None:
            rows = db.execute(
                "SELECT DISTINCT user_id FROM ws_presence WHERE updated_at>? AND conn_count>0 AND node_id<>?",
                (cutoff, _local_node_id),
            ).fetchall()
        else:
            rows = db.execute(
                "SELECT DISTINCT user_id FROM ws_presence WHERE updated_at>? AND conn_count>0",
                (cutoff,),
            ).fetchall()
        users |= {int(r[0]) for r in rows}
    except Exception:
        try:
            _presence_db.conn = None
        except Exception:
            pass
    return users

"""Minimal Redis-compatible (RESP2) pub/sub server.

Supports PING, ECHO, SUBSCRIBE, UNSUBSCRIBE, PSUBSCRIBE, PUNSUBSCRIBE, PUBLISH, QUIT, SELECT,
CLIENT, INFO, COMMAND, HELLO (RESP2 only), plus tiny GET/SET/DEL for tooling convenience.
Run: python3 -m huddle.miniredis [--port P]
"""
import argparse
import asyncio
import fnmatch
import os
import socket
import sys
import time

MAX_BUFFER = 64 * 1024 * 1024


def enc_simple(s):
    return b"+" + s.encode() + b"\r\n"


def enc_err(s):
    return b"-" + s.encode() + b"\r\n"


def enc_int(n):
    return b":%d\r\n" % n


def enc_bulk(b):
    if b is None:
        return b"$-1\r\n"
    if isinstance(b, str):
        b = b.encode()
    return b"$%d\r\n%s\r\n" % (len(b), b)


def enc_arr(items):
    out = [b"*%d\r\n" % len(items)]
    for it in items:
        if isinstance(it, int):
            out.append(enc_int(it))
        else:
            out.append(enc_bulk(it))
    return b"".join(out)


class Server:
    def __init__(self):
        self.channels = {}  # name(bytes) -> set(Client)
        self.patterns = {}  # pattern(bytes) -> set(Client)
        self.kv = {}
        self.started = time.time()
        self.clients = set()

    def publish(self, channel, message):
        n = 0
        msg = None
        for c in list(self.channels.get(channel, ())):
            if msg is None:
                msg = enc_arr([b"message", channel, message])
            c.send(msg)
            n += 1
        if self.patterns:
            ch_s = channel.decode("utf-8", "replace")
            for pat, subs in list(self.patterns.items()):
                if fnmatch.fnmatchcase(ch_s, pat.decode("utf-8", "replace")):
                    pm = enc_arr([b"pmessage", pat, channel, message])
                    for c in list(subs):
                        c.send(pm)
                        n += 1
        return n


class Client:
    def __init__(self, server, reader, writer):
        self.server = server
        self.reader = reader
        self.writer = writer
        self.chans = set()
        self.pats = set()
        self.closed = False

    def send(self, data):
        if self.closed:
            return
        tr = self.writer.transport
        if tr.is_closing():
            self.closed = True
            return
        if tr.get_write_buffer_size() > MAX_BUFFER:
            # slow consumer: drop it rather than grow without bound
            self.closed = True
            tr.abort()
            return
        self.writer.write(data)

    def subcount(self):
        return len(self.chans) + len(self.pats)

    def cleanup(self):
        self.closed = True
        for ch in self.chans:
            s = self.server.channels.get(ch)
            if s:
                s.discard(self)
                if not s:
                    del self.server.channels[ch]
        for p in self.pats:
            s = self.server.patterns.get(p)
            if s:
                s.discard(self)
                if not s:
                    del self.server.patterns[p]
        self.chans.clear()
        self.pats.clear()

    async def read_command(self):
        line = await self.reader.readline()
        if not line:
            return None
        if line[:1] == b"*":
            n = int(line[1:].strip() or 0)
            args = []
            for _ in range(n):
                hdr = await self.reader.readline()
                if not hdr:
                    return None
                if hdr[:1] != b"$":
                    raise ValueError("Protocol error: expected '$'")
                ln = int(hdr[1:].strip())
                data = await self.reader.readexactly(ln + 2)
                args.append(data[:-2])
            return args
        # inline command
        return line.strip().split()

    async def run(self):
        try:
            while True:
                try:
                    args = await self.read_command()
                except (ValueError, asyncio.IncompleteReadError) as e:
                    if isinstance(e, ValueError):
                        self.send(enc_err("ERR " + str(e)))
                    break
                if args is None:
                    break
                if not args:
                    continue
                if not self.dispatch(args):
                    break
                if self.writer.transport.get_write_buffer_size() > 1024 * 1024:
                    await self.writer.drain()
        except (ConnectionError, OSError):
            pass
        finally:
            self.cleanup()
            self.server.clients.discard(self)
            try:
                self.writer.close()
            except Exception:
                pass

    def dispatch(self, args):
        cmd = args[0].decode("utf-8", "replace").upper()
        a = args[1:]
        srv = self.server
        if self.subcount() and cmd not in ("SUBSCRIBE", "UNSUBSCRIBE", "PSUBSCRIBE", "PUNSUBSCRIBE",
                                           "PING", "QUIT", "RESET"):
            self.send(enc_err(f"ERR Can't execute '{cmd.lower()}': only (P)SUBSCRIBE / (P)UNSUBSCRIBE / PING / QUIT / RESET are allowed in this context"))
            return True
        if cmd == "PING":
            if self.subcount():
                self.send(enc_arr([b"pong", a[0] if a else b""]))
            else:
                self.send(enc_bulk(a[0]) if a else enc_simple("PONG"))
        elif cmd == "ECHO":
            if len(a) != 1:
                self.send(enc_err("ERR wrong number of arguments for 'echo' command"))
            else:
                self.send(enc_bulk(a[0]))
        elif cmd == "QUIT":
            self.send(enc_simple("OK"))
            return False
        elif cmd == "PUBLISH":
            if len(a) != 2:
                self.send(enc_err("ERR wrong number of arguments for 'publish' command"))
            else:
                self.send(enc_int(srv.publish(a[0], a[1])))
        elif cmd == "SUBSCRIBE":
            if not a:
                self.send(enc_err("ERR wrong number of arguments for 'subscribe' command"))
            for ch in a:
                if ch not in self.chans:
                    self.chans.add(ch)
                    srv.channels.setdefault(ch, set()).add(self)
                self.send(enc_arr([b"subscribe", ch, self.subcount()]))
        elif cmd == "PSUBSCRIBE":
            if not a:
                self.send(enc_err("ERR wrong number of arguments for 'psubscribe' command"))
            for p in a:
                if p not in self.pats:
                    self.pats.add(p)
                    srv.patterns.setdefault(p, set()).add(self)
                self.send(enc_arr([b"psubscribe", p, self.subcount()]))
        elif cmd == "UNSUBSCRIBE":
            targets = list(a) if a else list(self.chans)
            if not targets:
                self.send(enc_arr([b"unsubscribe", None, self.subcount()]) if False else
                          b"*3\r\n$11\r\nunsubscribe\r\n$-1\r\n" + enc_int(self.subcount()))
            for ch in targets:
                if ch in self.chans:
                    self.chans.discard(ch)
                    s = srv.channels.get(ch)
                    if s:
                        s.discard(self)
                        if not s:
                            del srv.channels[ch]
                self.send(enc_arr([b"unsubscribe", ch, self.subcount()]))
        elif cmd == "PUNSUBSCRIBE":
            targets = list(a) if a else list(self.pats)
            if not targets:
                self.send(b"*3\r\n$12\r\npunsubscribe\r\n$-1\r\n" + enc_int(self.subcount()))
            for p in targets:
                if p in self.pats:
                    self.pats.discard(p)
                    s = srv.patterns.get(p)
                    if s:
                        s.discard(self)
                        if not s:
                            del srv.patterns[p]
                self.send(enc_arr([b"punsubscribe", p, self.subcount()]))
        elif cmd == "RESET":
            self.cleanup()
            self.closed = False
            self.send(enc_simple("RESET"))
        elif cmd == "SELECT" or cmd == "AUTH":
            self.send(enc_simple("OK"))
        elif cmd == "HELLO":
            if a and a[0] not in (b"2",):
                self.send(enc_err("NOPROTO unsupported protocol version"))
            else:
                self.send(enc_arr([b"server", b"redis", b"version", b"7.0.0", b"proto", 2,
                                   b"id", id(self) & 0xFFFF, b"mode", b"standalone",
                                   b"role", b"master", b"modules"]).replace(b"*13\r\n", b"*14\r\n", 1)
                          + b"*0\r\n")
        elif cmd == "CLIENT":
            sub = a[0].decode().upper() if a else ""
            if sub == "GETNAME":
                self.send(enc_bulk(None))
            elif sub == "ID":
                self.send(enc_int(id(self) & 0xFFFFFF))
            elif sub == "LIST":
                self.send(enc_bulk(f"id={id(self) & 0xFFFFFF} cmd=client\n"))
            else:
                self.send(enc_simple("OK"))
        elif cmd == "INFO":
            info = (
                "# Server\r\nredis_version:7.0.0\r\nredis_mode:standalone\r\nprocess_id:%d\r\n"
                "tcp_port:%d\r\nuptime_in_seconds:%d\r\n# Clients\r\nconnected_clients:%d\r\n"
                "pubsub_channels:%d\r\n" % (os.getpid(), PORT, int(time.time() - srv.started),
                                           len(srv.clients), len(srv.channels))
            )
            self.send(enc_bulk(info))
        elif cmd == "COMMAND":
            if a and a[0].upper() == b"COUNT":
                self.send(enc_int(0))
            else:
                self.send(b"*0\r\n")
        elif cmd == "PUBSUB":
            sub = a[0].decode().upper() if a else ""
            if sub == "CHANNELS":
                self.send(enc_arr(list(srv.channels.keys())))
            elif sub == "NUMSUB":
                out = []
                for ch in a[1:]:
                    out += [ch, len(srv.channels.get(ch, ()))]
                self.send(enc_arr(out))
            elif sub == "NUMPAT":
                self.send(enc_int(len(srv.patterns)))
            else:
                self.send(enc_err("ERR unknown subcommand"))
        elif cmd == "SET" and len(a) >= 2:
            srv.kv[a[0]] = a[1]
            self.send(enc_simple("OK"))
        elif cmd == "GET" and len(a) == 1:
            self.send(enc_bulk(srv.kv.get(a[0])))
        elif cmd == "DEL" and a:
            self.send(enc_int(sum(1 for k in a if srv.kv.pop(k, None) is not None)))
        elif cmd == "DBSIZE":
            self.send(enc_int(len(srv.kv)))
        elif cmd == "FLUSHALL" or cmd == "FLUSHDB":
            srv.kv.clear()
            self.send(enc_simple("OK"))
        else:
            self.send(enc_err(f"ERR unknown command '{cmd.lower()}'"))
        return True


PORT = 6379


async def serve(port):
    server = Server()

    async def on_conn(reader, writer):
        sock = writer.get_extra_info("socket")
        try:
            sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        except Exception:
            pass
        c = Client(server, reader, writer)
        server.clients.add(c)
        await c.run()

    last_err = None
    for _ in range(100):  # the old process may still be releasing the port
        try:
            srv = await asyncio.start_server(on_conn, "127.0.0.1", port, reuse_address=True,
                                             limit=1024 * 1024 * 64)
            break
        except OSError as e:
            last_err = e
            await asyncio.sleep(0.1)
    else:
        raise last_err
    print(f"miniredis listening on 127.0.0.1:{port}", flush=True)
    async with srv:
        await srv.serve_forever()


def main(argv=None):
    global PORT
    from huddle import config
    ap = argparse.ArgumentParser()
    ap.add_argument("--port", type=int, default=config.REDIS_PORT)
    ap.add_argument("--bind", default="127.0.0.1")
    args, _unknown = ap.parse_known_args(argv if argv is not None else sys.argv[1:])
    PORT = args.port
    try:
        asyncio.run(serve(args.port))
    except KeyboardInterrupt:
        pass


if __name__ == "__main__":
    main()

"""Minimal asyncio HTTP/1.1 + RFC 6455 WebSocket client with failover across the HTTP nodes."""
import asyncio
import base64
import hashlib
import json
import os
import struct
import time
