WS_GUID = "258EAFA5-E914-47DA-95CA-C5AB0DC11B85"


class ClusterDown(Exception):
    pass


class _ConnectFailed(Exception):
    pass


async def _read_http_response(reader):
    head = await reader.readuntil(b"\r\n\r\n")
    lines = head.decode("latin-1").split("\r\n")
    parts = lines[0].split(" ", 2)
    status = int(parts[1])
    headers = {}
    for ln in lines[1:]:
        if ":" in ln:
            k, v = ln.split(":", 1)
            headers[k.strip().lower()] = v.strip()
    return status, headers


async def _read_body(reader, headers):
    if headers.get("transfer-encoding", "").lower() == "chunked":
        chunks = []
        while True:
            szline = await reader.readuntil(b"\r\n")
            size = int(szline.split(b";")[0].strip() or b"0", 16)
            if size == 0:
                # trailers
                while True:
                    ln = await reader.readuntil(b"\r\n")
                    if ln == b"\r\n":
                        break
                break
            chunks.append(await reader.readexactly(size))
            await reader.readexactly(2)
        return b"".join(chunks)
    if "content-length" in headers:
        n = int(headers["content-length"])
        return await reader.readexactly(n) if n else b""
    return await reader.read()


class Cluster:
    """REST client that fails over between the HTTP nodes."""

    def __init__(self, host, ports, timeout=6.0):
        self.host = host
        self.ports = list(ports)
        self.timeout = timeout
        self.pref = 0
        self.bad_until = {}  # port -> monotonic time until which we avoid it

    def order(self):
        n = len(self.ports)
        rot = [self.ports[(self.pref + i) % n] for i in range(n)]
        now = time.monotonic()
        good = [p for p in rot if self.bad_until.get(p, 0) <= now]
        bad = [p for p in rot if self.bad_until.get(p, 0) > now]
        return good + bad

    def mark_bad(self, port, secs=2.0):
        self.bad_until[port] = time.monotonic() + secs
        if self.ports[self.pref % len(self.ports)] == port:
            self.pref = (self.pref + 1) % len(self.ports)

    def mark_good(self, port):
        self.bad_until.pop(port, None)

    async def _once(self, port, method, path, token, body):
        try:
            reader, writer = await asyncio.wait_for(
                asyncio.open_connection(self.host, port), timeout=2.0)
        except (OSError, asyncio.TimeoutError) as e:
            raise _ConnectFailed(str(e))
        try:
            data = b""
            if body is not None:
                data = json.dumps(body).encode("utf-8")
            hdrs = [f"{method} {path} HTTP/1.1", f"Host: {self.host}:{port}",
                    "Connection: close", "Accept: application/json",
                    f"Content-Length: {len(data)}"]
            if body is not None:
                hdrs.append("Content-Type: application/json")
            if token:
                hdrs.append(f"Authorization: Bearer {token}")
            writer.write(("\r\n".join(hdrs) + "\r\n\r\n").encode("latin-1") + data)
            await writer.drain()

            async def _resp():
                st, hd = await _read_http_response(reader)
                return st, await _read_body(reader, hd)

            status, raw = await asyncio.wait_for(_resp(), timeout=self.timeout)
        finally:
            try:
                writer.close()
            except Exception:
                pass
        try:
            payload = json.loads(raw.decode("utf-8")) if raw else None
        except Exception:
            payload = None
        return status, payload

    async def request(self, method, path, token=None, body=None):
        """Returns (status, json). Raises ClusterDown if no node answered."""
        idempotent = method in ("GET", "HEAD", "PUT", "DELETE")
        last = None
        for attempt in range(2):
            for port in self.order():
                try:
                    status, payload = await self._once(port, method, path, token, body)
                except _ConnectFailed as e:
                    self.mark_bad(port)
                    last = e
                    continue
                except (OSError, asyncio.TimeoutError, asyncio.IncompleteReadError,
                        asyncio.LimitOverrunError, ValueError, IndexError) as e:
                    self.mark_bad(port)
                    last = e
                    if idempotent:
                        continue
                    raise ClusterDown(f"request failed after send: {e!r}")
                if status in (502, 503, 504):
                    self.mark_bad(port)
                    last = Exception(f"status {status}")
                    continue
                self.mark_good(port)
                return status, payload
            await asyncio.sleep(0.3)
        raise ClusterDown(str(last))


class WSClosed(Exception):
    pass


class WebSocket:
    def __init__(self, reader, writer, port):
        self.reader = reader
        self.writer = writer
        self.port = port
        self.closed = False

    @classmethod
    async def connect(cls, host, port, path, timeout=3.0):
        reader, writer = await asyncio.wait_for(asyncio.open_connection(host, port), timeout=timeout)
        try:
            key = base64.b64encode(os.urandom(16)).decode()
            req = (f"GET {path} HTTP/1.1\r\nHost: {host}:{port}\r\nUpgrade: websocket\r\n"
                   f"Connection: Upgrade\r\nSec-WebSocket-Key: {key}\r\n"
                   f"Sec-WebSocket-Version: 13\r\n\r\n")
            writer.write(req.encode("latin-1"))
            await writer.drain()
            status, headers = await asyncio.wait_for(_read_http_response(reader), timeout=timeout)
            if status != 101:
                raise WSClosed(f"upgrade rejected: {status}")
        except BaseException:
            writer.close()
            raise
        return cls(reader, writer, port)

    async def send(self, obj):
        if self.closed:
            raise WSClosed("closed")
        data = json.dumps(obj).encode("utf-8")
        self._send_frame(0x1, data)
        await self.writer.drain()

    def _send_frame(self, opcode, data):
        mask = os.urandom(4)
        n = len(data)
        hdr = bytes([0x80 | opcode])
        if n < 126:
            hdr += bytes([0x80 | n])
        elif n < 65536:
            hdr += bytes([0x80 | 126]) + struct.pack("!H", n)
        else:
            hdr += bytes([0x80 | 127]) + struct.pack("!Q", n)
        masked = bytes(b ^ mask[i & 3] for i, b in enumerate(data))
        self.writer.write(hdr + mask + masked)

    async def recv(self):
        """Return next text message (str). Raises WSClosed when the connection ends."""
        buf = []
        try:
            while True:
                h = await self.reader.readexactly(2)
                fin = h[0] & 0x80
                opcode = h[0] & 0x0F
                n = h[1] & 0x7F
                if n == 126:
                    n = struct.unpack("!H", await self.reader.readexactly(2))[0]
                elif n == 127:
                    n = struct.unpack("!Q", await self.reader.readexactly(8))[0]
                mask = await self.reader.readexactly(4) if h[1] & 0x80 else None
                payload = await self.reader.readexactly(n) if n else b""
                if mask:
                    payload = bytes(b ^ mask[i & 3] for i, b in enumerate(payload))
                if opcode == 0x8:
                    self.close()
                    raise WSClosed("close frame")
                if opcode == 0x9:
                    self._send_frame(0xA, payload)
                    continue
                if opcode == 0xA:
                    continue
                buf.append(payload)
                if fin:
                    return b"".join(buf).decode("utf-8", "replace")
        except (asyncio.IncompleteReadError, OSError) as e:
            self.close()
            raise WSClosed(str(e))

    def close(self):
        if not self.closed:
            self.closed = True
            try:
                self.writer.close()
            except Exception:
                pass


class EventStream:
    """One WS connection (with failover + resume) delivering channel frames for a token."""

    def __init__(self, cluster, token, on_frame):
        self.cluster = cluster
        self.token = token
        self.on_frame = on_frame
        self.channels = {}  # channel_id -> last seq (or None if not yet known)
        self.ws = None
        self.acks = {}  # channel_id -> Future
        self.task = None
        self.stopped = False
        self.connected = asyncio.Event()
        self.last_rx = time.monotonic()

    def start(self):
        self.task = asyncio.ensure_future(self._run())

    def stop(self):
        self.stopped = True
        if self.ws:
            self.ws.close()
        if self.task:
            self.task.cancel()

    async def subscribe(self, cid, timeout=3.0):
        """Subscribe to a channel; waits (bounded) for the server's ack."""
        if cid in self.channels and self.channels[cid] is not None:
            return
        self.channels.setdefault(cid, None)
        fut = asyncio.get_running_loop().create_future()
        self.acks[cid] = fut
        try:
            if not self.connected.is_set():
                await asyncio.wait_for(self.connected.wait(), timeout)
                # _on_connect will have sent subscribe already
            else:
                await self.ws.send({"type": "subscribe", "channel_id": cid})
            await asyncio.wait_for(asyncio.shield(fut), timeout)
        except (asyncio.TimeoutError, WSClosed, OSError, AttributeError):
            pass
        finally:
            if self.acks.get(cid) is fut:
                self.acks.pop(cid, None)

    def unsubscribe(self, cid):
        self.channels.pop(cid, None)
        ws = self.ws
        if ws and not ws.closed:
            async def _s():
                try:
                    await ws.send({"type": "unsubscribe", "channel_id": cid})
                except Exception:
                    pass
            asyncio.ensure_future(_s())

    async def _on_connect(self, ws):
        for cid, last in list(self.channels.items()):
            if last is None:
                await ws.send({"type": "subscribe", "channel_id": cid})
            else:
                await ws.send({"type": "resume", "channel_id": cid, "since_seq": last})

    def _ack(self, cid):
        fut = self.acks.get(cid)
        if fut and not fut.done():
            fut.set_result(True)

    def _handle(self, frame):
        t = frame.get("type")
        cid = frame.get("channel_id")
        if t == "subscribed":
            if cid in self.channels and self.channels[cid] is None:
                try:
                    self.channels[cid] = int(frame.get("head_seq") or 0)
                except (TypeError, ValueError):
                    self.channels[cid] = 0
            self._ack(cid)
            return
        if t == "resumed":
            if cid in self.channels and self.channels[cid] is None:
                self.channels[cid] = int(frame.get("head_seq") or 0)
            self._ack(cid)
            return
        if t == "resume.gap":
            # cannot replay; just continue live from here
            return
        seq = frame.get("seq")
        if cid is not None and seq is not None:
            if cid not in self.channels:
                return
            last = self.channels[cid]
            try:
                seq = int(seq)
            except (TypeError, ValueError):
                return
            if last is not None and seq <= last:
                return  # duplicate
            self.channels[cid] = seq
        self.on_frame(frame)

    async def _pinger(self, ws):
        try:
            while not ws.closed:
                await asyncio.sleep(10)
                if time.monotonic() - self.last_rx > 35:
                    ws.close()
                    return
                await ws.send({"type": "ping"})
        except Exception:
            ws.close()

    async def _run(self):
        backoff = 0.05
        while not self.stopped:
            ws = None
            for port in self.cluster.order():
                path = "/api/ws?token=" + urllib.parse.quote(self.token, safe="")
                try:
                    ws = await WebSocket.connect(self.cluster.host, port, path)
                    break
                except (OSError, asyncio.TimeoutError, WSClosed, asyncio.IncompleteReadError,
                        ValueError, IndexError):
                    self.cluster.mark_bad(port)
                    ws = None
            if ws is None:
                await asyncio.sleep(backoff)
                backoff = min(1.0, backoff * 2)
                continue
            backoff = 0.05
            self.ws = ws
            self.last_rx = time.monotonic()
            pinger = asyncio.ensure_future(self._pinger(ws))
            try:
                await self._on_connect(ws)
                self.connected.set()
                while True:
                    text = await ws.recv()
                    self.last_rx = time.monotonic()
                    try:
                        frame = json.loads(text)
                    except ValueError:
                        continue
                    if isinstance(frame, dict):
                        try:
                            self._handle(frame)
                        except Exception:
                            pass
            except (WSClosed, OSError, asyncio.IncompleteReadError):
                pass
            finally:
                self.connected.clear()
                pinger.cancel()
                ws.close()
                self.ws = None
            if not self.stopped:
                self.cluster.mark_bad(ws.port, 1.0)
                await asyncio.sleep(0.05)

"""Huddle IRC gateway: bridges IRC clients to the Huddle cluster over REST + WebSocket."""
import asyncio
import re
import sqlite3
import sys
import time
import urllib.parse

from huddle import config
from huddle.irc.cluster import Cluster, ClusterDown, EventStream

SERVER = "huddle"
VERSION = "huddle-irc-1.0"
SLUG_RE = re.compile(r"^[a-z0-9-]{2,32}$")
NICK_RE = re.compile(r"^[A-Za-z\[\]\\`_^{|}][A-Za-z0-9\[\]\\`_^{|}-]{0,31}$")
MAX_LINE = 16384
CREATED = time.strftime("%Y-%m-%d %H:%M:%S UTC", time.gmtime())


def log(*a):
    print("[irc]", *a, file=sys.stderr, flush=True)


def parse_line(line):
    """Parse an IRC line -> (command, params) or None."""
    line = line.strip("\r\n").lstrip()
    if not line:
        return None
    if line.startswith(":"):
        sp = line.find(" ")
        if sp < 0:
            return None
        line = line[sp + 1:].lstrip()
    trailing = None
    if " :" in line:
        line, trailing = line.split(" :", 1)
    elif line.startswith(":"):
        trailing = line[1:]
        line = ""
    params = line.split()
    if not params and trailing is None:
        return None
    if not params:
        return None
    cmd = params[0].upper()
    params = params[1:]
    if trailing is not None:
        params.append(trailing)
    return cmd, params


def clean(s):
    return str(s).replace("\r", " ").replace("\n", " ").replace("\0", "")


class Chan:
    __slots__ = ("id", "irc", "slug", "name", "topic", "ready")

    def __init__(self, cid, irc, slug, name, topic):
        self.id = cid
        self.irc = irc
        self.slug = slug
        self.name = name
        self.topic = topic or ""
        self.ready = asyncio.Event()


class Gateway:
    def __init__(self, cluster=None):
        self.cluster = cluster or Cluster(config.HOST, config.node_ports())
        self.nicks = {}  # lower nick -> Client
        self.clients = set()
        self.user_cache = {}  # user_id -> username

    async def handle(self, reader, writer):
        c = Client(self, reader, writer)
        self.clients.add(c)
        try:
            await c.run()
        except Exception as e:  # never let one client take down the gateway
            log("client error", repr(e))
        finally:
            c.cleanup()
            self.clients.discard(c)


class Client:
    def __init__(self, gw, reader, writer):
        self.gw = gw
        self.cluster = gw.cluster
        self.reader = reader
        self.writer = writer
        self.token = None
        self.user = None
        self.nick = None
        self.ident = None
        self.realname = ""
        self.registered = False
        self.closing = False
        self.chans = {}  # lower irc name -> Chan (joined)
        self.by_id = {}  # channel id -> Chan (joined)
        self.resolve_cache = {}  # lower irc name -> (cid, irc, slug, name, topic)
        self.stream = None
        self.events = asyncio.Queue()
        self.pump_task = None
        self.sent_ids = set()
        self.inflight = {}  # channel id -> count of in-flight posts
        self.post_done = asyncio.Condition()
        try:
            peer = writer.get_extra_info("peername")
            self.host = SERVER if not peer else SERVER
        except Exception:
            self.host = SERVER

    # ---------------------------------------------------------------- output
    @property
    def me(self):
        return self.nick or "*"

    @property
    def prefix(self):
        return f"{self.nick}!{self.uname}@{SERVER}"

    @property
    def uname(self):
        if self.user and self.user.get("username"):
            return clean(self.user["username"])
        return clean(self.ident or self.nick or "user")

    def send(self, line):
        if self.closing:
            return
        try:
            self.writer.write(line.encode("utf-8", "replace") + b"\r\n")
            transport = self.writer.transport
            if transport is not None and transport.get_write_buffer_size() > 4 * 1024 * 1024:
                log("client too slow; dropping")
                self.close()
        except Exception:
            self.close()

    def num(self, code, *args, trailing=None):
        parts = [f":{SERVER}", code, self.me] + [clean(a) for a in args]
        line = " ".join(parts)
        if trailing is not None:
            line += " :" + clean(trailing)
        self.send(line)

    def close(self):
        if self.closing:
            return
        self.closing = True
        try:
            self.writer.close()
        except Exception:
            pass

    def cleanup(self):
        self.close()
        if self.nick and self.gw.nicks.get(self.nick.lower()) is self:
            del self.gw.nicks[self.nick.lower()]
        if self.stream:
            self.stream.stop()
        if self.pump_task:
            self.pump_task.cancel()

    # ---------------------------------------------------------------- main loop
    async def run(self):
        buf = b""
        while not self.closing:
            try:
                data = await asyncio.wait_for(self.reader.read(8192), timeout=600)
            except asyncio.TimeoutError:
                self.send(f"ERROR :Closing link (ping timeout)")
                break
            except (OSError, ConnectionError):
                break
            if not data:
                break
            buf += data
            while b"\n" in buf and not self.closing:
                raw, buf = buf.split(b"\n", 1)
                await self.dispatch(raw)
            if len(buf) > MAX_LINE:
                buf = b""
            try:
                await self.writer.drain()
            except Exception:
                break
        # flush whatever is queued
        try:
            await asyncio.wait_for(self.writer.drain(), timeout=1)
        except Exception:
            pass

    async def dispatch(self, raw):
        try:
            line = raw.decode("utf-8")
        except UnicodeDecodeError:
            line = raw.decode("latin-1")
        try:
            parsed = parse_line(line)
        except Exception:
            parsed = None
        if not parsed:
            return
        cmd, params = parsed
        handler = getattr(self, "cmd_" + cmd, None) if cmd.isalpha() else None
        if handler is None:
            if not self.registered and cmd not in ("PRIVMSG", "NOTICE"):
                self.num("421", cmd, trailing="Unknown command")
            elif not self.registered:
                self.num("451", trailing="You have not registered")
            else:
                self.num("421", cmd, trailing="Unknown command")
            return
        if not self.registered and cmd not in PRE_REG:
            self.num("451", trailing="You have not registered")
            return
        try:
            await handler(params)
        except ClusterDown as e:
            log("cluster down", e)
            self.send(f":{SERVER} NOTICE {self.me} :Huddle backend unavailable, try again")
        except Exception as e:
            log("command error", cmd, repr(e))

    # ---------------------------------------------------------------- REST helpers
    async def api(self, method, path, body=None):
        return await self.cluster.request(method, path, token=self.token, body=body)

    # ---------------------------------------------------------------- registration
    async def cmd_CAP(self, p):
        sub = p[0].upper() if p else ""
        if sub == "LS":
            self.send(f":{SERVER} CAP {self.me} LS :")
        elif sub == "LIST":
            self.send(f":{SERVER} CAP {self.me} LIST :")
        elif sub == "REQ":
            self.send(f":{SERVER} CAP {self.me} NAK :{p[1] if len(p) > 1 else ''}")
        # END and others: ignore

    async def cmd_PASS(self, p):
        if self.registered:
            self.num("462", trailing="You may not reregister")
            return
        if not p:
            self.num("461", "PASS", trailing="Not enough parameters")
            return
        tok = p[0].strip()
        if tok.lower().startswith("bearer "):
            tok = tok[7:].strip()
        self.token = tok

    async def cmd_NICK(self, p):
        if not p or not p[0].strip():
            self.num("431", trailing="No nickname given")
            return
        new = p[0].strip()
        if not NICK_RE.match(new):
            self.num("432", new, trailing="Erroneous nickname")
            return
        low = new.lower()
        holder = self.gw.nicks.get(low)
        if holder is not None and holder is not self:
            self.num("433", new, trailing="Nickname is already in use")
            return
        old = self.nick
        if old and self.gw.nicks.get(old.lower()) is self:
            del self.gw.nicks[old.lower()]
        self.gw.nicks[low] = self
        if self.registered:
            if old != new:
                self.send(f":{old}!{self.uname}@{SERVER} NICK :{new}")
            self.nick = new
        else:
            self.nick = new
            await self.try_register()

    async def cmd_USER(self, p):
        if self.registered:
            self.num("462", trailing="You may not reregister")
            return
        if len(p) < 1:
            self.num("461", "USER", trailing="Not enough parameters")
            return
        self.ident = p[0]
        self.realname = p[-1] if len(p) >= 4 else p[0]
        await self.try_register()

    async def try_register(self):
        if self.registered or not self.nick or not self.ident:
            return
        if not self.token:
            self.num("464", trailing="Password incorrect")
            self.send(f"ERROR :Closing link: {self.nick} (Password required)")
            self.close()
            return
        try:
            status, payload = await self.api("GET", "/api/auth/me")
        except ClusterDown:
            self.send(f"ERROR :Closing link: backend unavailable")
            self.close()
            return
        if status != 200 or not isinstance(payload, dict) or not isinstance(payload.get("user"), dict):
            self.num("464", trailing="Password incorrect")
            self.send(f"ERROR :Closing link: {self.nick} (Bad password)")
            self.close()
            return
        self.user = payload["user"]
        if self.nick is None or self.closing:
            return
        self.registered = True
        if self.user.get("id") is not None:
            self.gw.user_cache[self.user["id"]] = self.user.get("username")
        n = self.nick
        self.num("001", trailing=f"Welcome to the Huddle IRC gateway {self.prefix}")
        self.num("002", trailing=f"Your host is {SERVER}, running version {VERSION}")
        self.num("003", trailing=f"This server was created {CREATED}")
        self.num("004", SERVER, VERSION, "io", "ntk")
        self.num("005", "CHANTYPES=#", "CHANMODES=b,k,l,nt", "PREFIX=(ov)@+", "NETWORK=Huddle",
                 "CASEMAPPING=ascii", "NICKLEN=32", "CHANNELLEN=80", "TOPICLEN=250",
                 trailing="are supported by this server")
        self.num("422", trailing="MOTD File is missing")
        self.stream = EventStream(self.cluster, self.token, self._on_frame)
        self.stream.start()
        self.pump_task = asyncio.ensure_future(self._pump())
        del n

    # ---------------------------------------------------------------- simple commands
    async def cmd_PING(self, p):
        tok = p[0] if p else SERVER
        self.send(f":{SERVER} PONG {SERVER} :{clean(tok)}")

    async def cmd_PONG(self, p):
        pass

    async def cmd_QUIT(self, p):
        self.close()

    async def cmd_MOTD(self, p):
        self.num("422", trailing="MOTD File is missing")

    async def cmd_NOTICE(self, p):
        if len(p) < 2:
            return
        for target in p[0].split(","):
            if target.startswith("#"):
                try:
                    await self._post(target, p[1], quiet=True)
                except ClusterDown:
                    pass

    async def cmd_AWAY(self, p):
        if p and p[0]:
            self.num("306", trailing="You have been marked as being away")
        else:
            self.num("305", trailing="You are no longer marked as being away")

    async def cmd_ISON(self, p):
        names = " ".join(p).split()
        on = [self.gw.nicks[n.lower()].nick for n in names if n.lower() in self.gw.nicks]
        self.num("303", trailing=" ".join(on))

    async def cmd_USERHOST(self, p):
        out = []
        for n in p[:5]:
            c = self.gw.nicks.get(n.lower())
            if c and c.registered:
                out.append(f"{c.nick}=+{c.uname}@{SERVER}")
        self.num("302", trailing=" ".join(out))

    async def cmd_WHOIS(self, p):
        if not p:
            self.num("431", trailing="No nickname given")
            return
        n = p[-1]
        c = self.gw.nicks.get(n.lower())
        if not c or not c.registered:
            self.num("401", n, trailing="No such nick/channel")
        else:
            self.num("311", c.nick, c.uname, SERVER, "*", trailing=c.realname or c.uname)
            self.num("312", c.nick, SERVER, trailing="Huddle IRC gateway")
        self.num("318", n, trailing="End of /WHOIS list.")

    async def cmd_MODE(self, p):
        if not p:
            self.num("461", "MODE", trailing="Not enough parameters")
            return
        target = p[0]
        if target.startswith("#"):
            if len(p) >= 2:
                if p[1].lstrip("+-") in ("b", "e", "I"):
                    code = {"b": ("368", "End of channel ban list"),
                            "e": ("349", "End of channel exception list"),
                            "I": ("347", "End of channel invite list")}[p[1].lstrip("+-")]
                    self.num(code[0], target, trailing=code[1])
                return  # mode changes silently ignored
            self.num("324", target, "+nt")
            self.num("329", target, str(int(time.time())))
        else:
            if target.lower() != (self.nick or "").lower():
                self.num("502", trailing="Can't change mode for other users")
                return
            if len(p) == 1:
                self.num("221", "+i")

    # ---------------------------------------------------------------- channel resolution
    async def _workspace_detail(self, slug):
        st, pl = await self.api("GET", "/api/workspaces/" + urllib.parse.quote(slug, safe=""))
        if st == 200 and isinstance(pl, dict):
            return pl
        return None

    def _remember(self, slug, channels):
        for ch in channels or []:
            if not isinstance(ch, dict) or ch.get("is_dm") or ch.get("name") is None:
                continue
            irc = f"#{slug}-{ch['name']}"
            self.resolve_cache[irc.lower()] = (ch.get("id"), irc, slug, ch["name"], ch.get("topic") or "")

    async def resolve(self, target):
        """Map '#slug-name' to (cid, irc, slug, name, topic) or None."""
        key = target.lower()
        if not key.startswith("#") or len(key) < 4:
            return None
        if key in self.resolve_cache:
            return self.resolve_cache[key]
        body = key[1:]
        tried = set()
        # 1) workspaces the user belongs to
        st, pl = await self.api("GET", "/api/workspaces")
        slugs = []
        if st == 200 and isinstance(pl, dict):
            for w in pl.get("workspaces") or []:
                if isinstance(w, dict) and w.get("slug"):
                    slugs.append(w["slug"])
        cands = sorted((s for s in slugs if body.startswith(s.lower() + "-")), key=len, reverse=True)
        for slug in cands:
            tried.add(slug.lower())
            d = await self._workspace_detail(slug)
            if d:
                self._remember(slug, d.get("channels"))
                if key in self.resolve_cache:
                    return self.resolve_cache[key]
        # 2) any other split (workspaces the user is not yet a member of)
        for i in range(len(body) - 1, 1, -1):
            if body[i] != "-":
                continue
            slug = body[:i]
            if slug in tried or not SLUG_RE.match(slug) or not body[i + 1:]:
                continue
            tried.add(slug)
            d = await self._workspace_detail(slug)
            if d:
                ws = d.get("workspace") or {}
                real = ws.get("slug") or slug
                self._remember(real, d.get("channels"))
                if key in self.resolve_cache:
                    return self.resolve_cache[key]
        # 3) read-only lookup in the shared store (public channels of other workspaces)
        hit = await asyncio.get_running_loop().run_in_executor(None, _db_lookup, body)
        if hit:
            self.resolve_cache[key] = hit
            return hit
        return None

    # ---------------------------------------------------------------- JOIN / PART / NAMES
    async def cmd_JOIN(self, p):
        if not p:
            self.num("461", "JOIN", trailing="Not enough parameters")
            return
        if p[0] == "0":
            for ch in list(self.chans.values()):
                await self._part(ch, "Leaving")
            return
        for target in p[0].split(","):
            target = target.strip()
            if not target:
                continue
            if not target.startswith("#"):
                self.num("403", target, trailing="No such channel")
                continue
            if target.lower() in self.chans:
                continue
            await self._join(target)

    async def _join(self, target):
        info = await self.resolve(target)
        if not info:
            self.num("403", target, trailing="No such channel")
            return
        cid, irc, slug, name, topic = info
        st, pl = await self.api("POST", f"/api/channels/{cid}/join", {})
        if st == 404:
            self.resolve_cache.pop(target.lower(), None)
            self.num("403", target, trailing="No such channel")
            return
        if st == 403:
            self.num("473", irc, trailing="Cannot join channel (+i)")
            return
        if st >= 400 and st != 423 and st != 409:
            self.num("403", target, trailing="No such channel")
            return
        if isinstance(pl, dict) and isinstance(pl.get("channel"), dict):
            topic = pl["channel"].get("topic") or topic or ""
        ch = Chan(cid, irc, slug, name, topic)
        self.chans[irc.lower()] = ch
        self.by_id[cid] = ch
        # subscribe before announcing so nothing posted after our JOIN reply is missed
        if self.stream:
            await self.stream.subscribe(cid)
        if self.closing:
            return
        self.send(f":{self.prefix} JOIN {irc}")
        if ch.topic:
            self.num("332", irc, trailing=ch.topic)
        else:
            self.num("331", irc, trailing="No topic is set")
        await self._names(ch)
        ch.ready.set()

    async def _members(self, cid):
        st, pl = await self.api("GET", f"/api/channels/{cid}/members")
        out = []
        if st == 200 and isinstance(pl, dict):
            for m in pl.get("members") or []:
                if isinstance(m, dict):
                    u = m.get("user") if isinstance(m.get("user"), dict) else m
                    if u.get("username"):
                        out.append(u)
        return out

    def _member_nick(self, u):
        if self.user and u.get("id") == self.user.get("id"):
            return self.nick
        return clean(u.get("username")).replace(" ", "_")

    async def _names(self, ch):
        try:
            members = await self._members(ch.id)
        except ClusterDown:
            members = []
        nicks = []
        for u in members:
            n = self._member_nick(u)
            if n and n not in nicks:
                nicks.append(n)
        if self.nick not in nicks:
            nicks.append(self.nick)
        line = []
        for n in nicks:
            line.append(n)
            if len(" ".join(line)) > 380:
                self.num("353", "=", ch.irc, trailing=" ".join(line))
                line = []
        if line:
            self.num("353", "=", ch.irc, trailing=" ".join(line))
        self.num("366", ch.irc, trailing="End of /NAMES list.")

    async def cmd_NAMES(self, p):
        if not p:
            self.num("366", "*", trailing="End of /NAMES list.")
            return
        for target in p[0].split(","):
            ch = self.chans.get(target.lower())
            if ch is None:
                info = await self.resolve(target)
                if info:
                    ch = Chan(*info)
            if ch is None:
                self.num("366", target, trailing="End of /NAMES list.")
                continue
            await self._names(ch)

    async def cmd_PART(self, p):
        if not p:
            self.num("461", "PART", trailing="Not enough parameters")
            return
        reason = p[1] if len(p) > 1 else "Leaving"
        for target in p[0].split(","):
            ch = self.chans.get(target.lower())
            if ch is None:
                self.num("442", target, trailing="You're not on that channel")
                continue
            await self._part(ch, reason)

    async def _part(self, ch, reason):
        self.chans.pop(ch.irc.lower(), None)
        self.by_id.pop(ch.id, None)
        if self.stream:
            self.stream.unsubscribe(ch.id)
        self.send(f":{self.prefix} PART {ch.irc} :{clean(reason)}")

    async def cmd_WHO(self, p):
        mask = p[0] if p else "*"
        if mask.startswith("#"):
            ch = self.chans.get(mask.lower())
            if ch is None:
                info = await self.resolve(mask)
                ch = Chan(*info) if info else None
            if ch is not None:
                for u in await self._members(ch.id):
                    n = self._member_nick(u)
                    real = clean(u.get("display_name") or u.get("username"))
                    self.num("352", ch.irc, clean(u.get("username")), SERVER, SERVER, n, "H",
                             trailing=f"0 {real}")
        else:
            c = self.gw.nicks.get(mask.lower())
            if c and c.registered:
                self.num("352", "*", c.uname, SERVER, SERVER, c.nick, "H", trailing=f"0 {c.realname}")
        self.num("315", mask, trailing="End of /WHO list.")

    async def cmd_LIST(self, p):
        wanted = None
        if p and p[0].startswith("#"):
            wanted = {t.lower() for t in p[0].split(",")}
        self.num("321", "Channel", trailing="Users  Name")
        st, pl = await self.api("GET", "/api/workspaces")
        if st == 200 and isinstance(pl, dict):
            for w in pl.get("workspaces") or []:
                if not isinstance(w, dict) or not w.get("slug"):
                    continue
                d = await self._workspace_detail(w["slug"])
                if not d:
                    continue
                self._remember(w["slug"], d.get("channels"))
                for c in d.get("channels") or []:
                    if not isinstance(c, dict) or c.get("is_dm") or c.get("is_archived"):
                        continue
                    irc = f"#{w['slug']}-{c.get('name')}"
                    if wanted and irc.lower() not in wanted:
                        continue
                    count = c.get("member_count") or c.get("members_count") or 0
                    self.num("322", irc, str(count), trailing=c.get("topic") or "")
        self.num("323", trailing="End of /LIST")

    async def cmd_TOPIC(self, p):
        if not p:
            self.num("461", "TOPIC", trailing="Not enough parameters")
            return
        target = p[0]
        ch = self.chans.get(target.lower())
        if len(p) == 1:
            if ch is None:
                info = await self.resolve(target)
                if not info:
                    self.num("403", target, trailing="No such channel")
                    return
                cid, irc, _s, _n, topic = info
            else:
                cid, irc, topic = ch.id, ch.irc, ch.topic
            if topic:
                self.num("332", irc, trailing=topic)
            else:
                self.num("331", irc, trailing="No topic is set")
            return
        if ch is None:
            self.num("442", target, trailing="You're not on that channel")
            return
        new = p[1]
        old = ch.topic
        ch.topic = new
        st, pl = await self.api("PATCH", f"/api/channels/{ch.id}", {"topic": new})
        if st == 200:
            if isinstance(pl, dict) and isinstance(pl.get("channel"), dict):
                ch.topic = pl["channel"].get("topic") or ""
            self.send(f":{self.prefix} TOPIC {ch.irc} :{clean(ch.topic)}")
        else:
            ch.topic = old
            if st == 403:
                self.num("482", ch.irc, trailing="You're not channel operator")
            else:
                self.num("442", ch.irc, trailing="Cannot set topic")

    # ---------------------------------------------------------------- PRIVMSG
    async def cmd_PRIVMSG(self, p):
        if not p:
            self.num("411", trailing="No recipient given (PRIVMSG)")
            return
        if len(p) < 2 or p[1] == "":
            self.num("412", trailing="No text to send")
            return
        for target in p[0].split(","):
            if target.startswith("#"):
                await self._post(target, p[1])
            else:
                self.num("401", target, trailing="No such nick/channel")

    async def _post(self, target, text, quiet=False):
        ch = self.chans.get(target.lower())
        if ch is not None:
            cid = ch.id
        else:
            info = await self.resolve(target)
            if not info:
                if not quiet:
                    self.num("403", target, trailing="No such channel")
                return
            cid = info[0]
        if text.startswith("\x01ACTION") :
            text = "/me " + text[7:].strip("\x01").strip()
        elif text.startswith("\x01"):
            return  # other CTCP: ignore
        if not text.strip():
            return
        self.inflight[cid] = self.inflight.get(cid, 0) + 1
        try:
            st, pl = await self.api("POST", f"/api/channels/{cid}/messages", {"body": text})
        finally:
            self.inflight[cid] -= 1
            if self.inflight[cid] <= 0:
                del self.inflight[cid]
        if st in (200, 201) and isinstance(pl, dict):
            msg = pl.get("message")
            if isinstance(msg, dict) and msg.get("id") is not None:
                self.sent_ids.add(msg["id"])
                if len(self.sent_ids) > 5000:
                    self.sent_ids = set(list(self.sent_ids)[-2000:])
        elif not quiet:
            self.num("404", target, trailing=f"Cannot send to channel ({st})")
        async with self.post_done:
            self.post_done.notify_all()

    # ---------------------------------------------------------------- WS -> IRC
    def _on_frame(self, frame):
        self.events.put_nowait(frame)

    async def _author_nick(self, msg):
        a = msg.get("author")
        if isinstance(a, dict) and a.get("username"):
            uname = a["username"]
        else:
            aid = msg.get("author_id")
            uname = self.gw.user_cache.get(aid)
            if not uname and aid is not None:
                try:
                    st, pl = await self.api("GET", f"/api/users/{aid}")
                    if st == 200 and isinstance(pl, dict) and isinstance(pl.get("user"), dict):
                        uname = pl["user"].get("username")
                        self.gw.user_cache[aid] = uname
                except ClusterDown:
                    pass
            uname = uname or f"user{aid}"
        uname = clean(uname).replace(" ", "_")
        if self.user and msg.get("author_id") == self.user.get("id"):
            return self.nick, uname
        return uname, uname

    async def _pump(self):
        while not self.closing:
            frame = await self.events.get()
            try:
                await self._deliver(frame)
            except asyncio.CancelledError:
                raise
            except Exception as e:
                log("deliver error", repr(e))

    async def _deliver(self, frame):
        cid = frame.get("channel_id")
        ch = self.by_id.get(cid)
        if ch is None:
            return
        if not ch.ready.is_set():
            try:
                await asyncio.wait_for(ch.ready.wait(), 5)
            except asyncio.TimeoutError:
                pass
            if self.by_id.get(cid) is not ch:
                return
        t = frame.get("type")
        if t in ("message.new", "message.reply"):
            msg = frame.get("message")
            if not isinstance(msg, dict):
                return
            mid = msg.get("id")
            mine = self.user is not None and msg.get("author_id") == self.user.get("id")
            if mine and mid not in self.sent_ids and self.inflight.get(cid):
                # our own POST may still be in flight; wait for it to report its id
                deadline = time.monotonic() + 5
                async with self.post_done:
                    while (mid not in self.sent_ids and self.inflight.get(cid)
                           and time.monotonic() < deadline):
                        try:
                            await asyncio.wait_for(self.post_done.wait(), 0.5)
                        except asyncio.TimeoutError:
                            pass
            if mid in self.sent_ids:
                self.sent_ids.discard(mid)
                return
            body = msg.get("body") or ""
            nick, uname = await self._author_nick(msg)
            for ln in str(body).replace("\r\n", "\n").replace("\r", "\n").split("\n"):
                if not ln.strip():
                    continue
                if ln.startswith("/me ") and False:
                    ln = f"\x01ACTION {ln[4:]}\x01"
                self.send(f":{nick}!{uname}@{SERVER} PRIVMSG {ch.irc} :{ln}")
        elif t == "channel.updated":
            c = frame.get("channel")
            if isinstance(c, dict) and "topic" in c:
                topic = c.get("topic") or ""
                if topic != ch.topic:
                    ch.topic = topic
                    self.send(f":{SERVER}!{SERVER}@{SERVER} TOPIC {ch.irc} :{clean(topic)}")
        try:
            await self.writer.drain()
        except Exception:
            pass


PRE_REG = {"PASS", "NICK", "USER", "CAP", "PING", "PONG", "QUIT"}


def _db_lookup(body):
    """Read-only fallback: find a public channel whose '#slug-name' matches (lower-cased)."""
    try:
        conn = sqlite3.connect(f"file:{config.DB_PATH}?mode=ro", uri=True, timeout=2)
    except Exception:
        return None
    try:
        conn.row_factory = sqlite3.Row
        rows = conn.execute(
            "SELECT c.*, w.slug AS ws_slug FROM channels c JOIN workspaces w ON w.id = c.workspace_id "
            "WHERE lower(w.slug || '-' || c.name) = ? AND COALESCE(c.is_dm, 0) = 0", (body,)).fetchall()
        for r in rows:
            keys = r.keys()
            if "is_private" in keys and r["is_private"]:
                continue
            topic = r["topic"] if "topic" in keys else ""
            slug = r["ws_slug"]
            return (r["id"], f"#{slug}-{r['name']}", slug, r["name"], topic or "")
    except Exception:
        return None
    finally:
        conn.close()
    return None


async def serve(host="0.0.0.0", port=None):
    port = port or config.IRC_PORT
    gw = Gateway()
    while True:
        try:
            server = await asyncio.start_server(gw.handle, host, port, reuse_address=True, limit=MAX_LINE * 4)
            break
        except OSError as e:
            log(f"bind {host}:{port} failed: {e}; retrying")
            await asyncio.sleep(0.5)
    log(f"listening on {host}:{port}; nodes {config.node_ports()}")
    async with server:
        await server.serve_forever()

