# WebSocket framing

def ws_frame(opcode, payload: bytes) -> bytes:
    n = len(payload)
    b0 = 0x80 | opcode
    if n < 126:
        hdr = bytes((b0, n))
    elif n < 65536:
        hdr = struct.pack(">BBH", b0, 126, n)
    else:
        hdr = struct.pack(">BBQ", b0, 127, n)
    return hdr + payload


def ws_text(obj) -> bytes:
    return ws_frame(0x1, json.dumps(obj, separators=(",", ":")).encode("utf-8"))


def unmask(data: bytes, mask: bytes) -> bytes:
    n = len(data)
    if n == 0:
        return data
    m = (mask * (n // 4 + 1))[:n]
    return (int.from_bytes(data, "big") ^ int.from_bytes(m, "big")).to_bytes(n, "big")


class WSConn:
    __slots__ = ("user_id", "writer", "subs", "closed", "hub")

    def __init__(self, hub, user_id, writer):
        self.hub = hub
        self.user_id = user_id
        self.writer = writer
        self.subs = {}  # channel_id -> last seq sent to this client
        self.closed = False

    def write(self, data: bytes):
        if self.closed:
            return
        tr = self.writer.transport
        if tr is None or tr.is_closing():
            self.closed = True
            return
        if tr.get_write_buffer_size() > WS_MAX_BUFFER:
            log("dropping slow websocket client user", self.user_id)
            self.closed = True
            tr.abort()
            return
        self.writer.write(data)

    def send(self, obj):
        self.write(ws_text(obj))


# ---------------------------------------------------------------------------------------------
# Hub: per-node fan-out state (only touched on the event loop thread)

class Hub:
    def __init__(self, loop):
        self.loop = loop
        self.db = None
        self.conns = set()
        self.chan_subs = {}     # channel_id -> set[WSConn]
        self.chan_last = {}     # channel_id -> last seq emitted by this node (dense)
        self.pending = {}       # channel_id -> {seq: frame}
        self.fill_scheduled = set()
        self.seen_global = collections.OrderedDict()
        self.user_counts = {}
        self.online = frozenset()
        self.presence_dirty = threading.Event()

    # -- db -------------------------------------------------------------------------------
    def q(self, sql, args=()):
        for attempt in range(3):
            try:
                if self.db is None:
                    self.db = config.connect()
                return self.db.execute(sql, args).fetchall()
            except Exception:
                try:
                    self.db.close()
                except Exception:
                    pass
                self.db = None
                if attempt == 2:
                    raise
                time.sleep(0.01)

    def head(self, ch):
        return int(self.q("SELECT COALESCE(MAX(seq),0) FROM channel_events WHERE channel_id=?", (ch,))[0][0])

    # -- connections ----------------------------------------------------------------------
    def add_conn(self, c):
        self.conns.add(c)
        self.user_counts[c.user_id] = self.user_counts.get(c.user_id, 0) + 1
        self.online = frozenset(self.user_counts)
        self.presence_dirty.set()

    def remove_conn(self, c):
        c.closed = True
        if c in self.conns:
            self.conns.discard(c)
            n = self.user_counts.get(c.user_id, 0) - 1
            if n <= 0:
                self.user_counts.pop(c.user_id, None)
            else:
                self.user_counts[c.user_id] = n
            self.online = frozenset(self.user_counts)
            self.presence_dirty.set()
        for ch in list(c.subs):
            self._unsub(c, ch)

    def _unsub(self, c, ch):
        c.subs.pop(ch, None)
        s = self.chan_subs.get(ch)
        if s is not None:
            s.discard(c)
            if not s:
                del self.chan_subs[ch]
                self.chan_last.pop(ch, None)
                self.pending.pop(ch, None)

    def subscribe(self, c, ch, last):
        """Register c on ch with its last-seen seq (caller holds the loop: atomic w.r.t. delivery)."""
        if ch not in self.chan_last:
            self.chan_last[ch] = self.head(ch)
        self.chan_subs.setdefault(ch, set()).add(c)
        c.subs[ch] = max(last, c.subs.get(ch, -1))

    # -- delivery -------------------------------------------------------------------------
    def on_frame(self, frame):
        try:
            ch = int(frame.get("channel_id"))
            seq = int(frame.get("seq"))
        except Exception:
            return
        last = self.chan_last.get(ch)
        if last is None or seq <= last:
            return
        if seq == last + 1:
            self._emit(ch, frame)
            self._drain(ch)
        else:
            self.pending.setdefault(ch, {})[seq] = frame
            if ch not in self.fill_scheduled:
                self.fill_scheduled.add(ch)
                self.loop.call_later(GAP_HOLD, self._fill, ch)

    def _drain(self, ch):
        pend = self.pending.get(ch)
        if not pend:
            return
        last = self.chan_last[ch]
        while pend:
            f = pend.pop(last + 1, None)
            if f is None:
                break
            self._emit(ch, f)
            last += 1
        for s in [s for s in pend if s <= last]:
            del pend[s]

    def _fill(self, ch):
        self.fill_scheduled.discard(ch)
        pend = self.pending.get(ch)
        last = self.chan_last.get(ch)
        if not pend or last is None:
            return
        target = max(pend)
        try:
            rows = self.q(
                "SELECT seq, payload FROM channel_events WHERE channel_id=? AND seq>? AND seq<=? ORDER BY seq",
                (ch, last, target),
            )
        except Exception as e:
            log("gap fill failed", e)
            rows = []
        for seq, payload in rows:
            if seq == self.chan_last[ch] + 1:
                f = pend.pop(seq, None) or json.loads(payload)
                self._emit(ch, f)
        self._drain(ch)
        if self.pending.get(ch) and ch not in self.fill_scheduled:
            self.fill_scheduled.add(ch)
            self.loop.call_later(0.1, self._fill, ch)

    def _emit(self, ch, frame):
        seq = frame["seq"]
        self.chan_last[ch] = seq
        subs = self.chan_subs.get(ch)
        if not subs:
            return
        data = None
        for c in list(subs):
            if c.subs.get(ch, seq) < seq:
                c.subs[ch] = seq
                if data is None:
                    data = ws_text(frame)
                c.write(data)

    def on_global(self, uid, frame):
        if uid in self.seen_global:
            return
        self.seen_global[uid] = True
        if len(self.seen_global) > 20000:
            self.seen_global.popitem(last=False)
        if not self.conns:
            return
        data = ws_text(frame)
        for c in list(self.conns):
            c.write(data)

    def on_local(self, kind, frame, uid):
        if kind == "g":
            self.on_global(uid, frame)
        else:
            self.on_frame(frame)

    def on_tail(self, rows, grows):
        for _id, ch, seq, payload in rows:
            last = self.chan_last.get(ch)
            if last is not None and seq > last:
                try:
                    self.on_frame(json.loads(payload))
                except Exception:
                    pass
        for _id, uid, payload in grows:
            if uid not in self.seen_global:
                try:
                    self.on_global(uid, json.loads(payload))
                except Exception:
                    pass


