# ---------------------------------------------------------------------------------------------
# background threads: sqlite tail + presence heartbeat

def tail_thread(loop, hub):
    db = None
    last_id = None
    glast_id = None
    while True:
        try:
            if db is None:
                db = config.connect()
                events.ensure_schema(db)
            if last_id is None:
                last_id = db.execute("SELECT COALESCE(MAX(id),0) FROM channel_events").fetchone()[0]
                glast_id = db.execute("SELECT COALESCE(MAX(id),0) FROM global_events").fetchone()[0]
            rows = db.execute(
                "SELECT id, channel_id, seq, payload FROM channel_events WHERE id>? ORDER BY id LIMIT 5000",
                (last_id,),
            ).fetchall()
            grows = db.execute(
                "SELECT id, uid, payload FROM global_events WHERE id>? ORDER BY id LIMIT 1000", (glast_id,)
            ).fetchall()
            if rows or grows:
                if rows:
                    last_id = rows[-1][0]
                if grows:
                    glast_id = grows[-1][0]
                loop.call_soon_threadsafe(
                    hub.on_tail, [tuple(r) for r in rows], [tuple(r) for r in grows]
                )
                if len(rows) == 5000:
                    continue
        except Exception as e:
            log("tail error", e)
            try:
                db.close()
            except Exception:
                pass
            db = None
        time.sleep(TAIL_INTERVAL)


def presence_thread(hub):
    db = None
    while True:
        try:
            if db is None:
                db = config.connect()
                events.ensure_schema(db)
            users = hub.online
            now = time.time()
            db.execute("BEGIN IMMEDIATE")
            try:
                db.execute("DELETE FROM ws_presence WHERE node_id=?", (NODE_ID,))
                if users:
                    counts = dict(hub.user_counts) if True else {}
                    db.executemany(
                        "INSERT OR REPLACE INTO ws_presence(node_id,user_id,conn_count,updated_at) VALUES(?,?,?,?)",
                        [(NODE_ID, u, counts.get(u, 1), now) for u in users],
                    )
                db.execute("COMMIT")
            except Exception:
                try:
                    db.execute("ROLLBACK")
                except Exception:
                    pass
                raise
        except Exception as e:
            log("presence error", e)
            try:
                db.close()
            except Exception:
                pass
            db = None
        hub.presence_dirty.wait(PRESENCE_INTERVAL)
        hub.presence_dirty.clear()


# ---------------------------------------------------------------------------------------------
# redis subscriber (fast path for remote events)

async def _resp_read(reader):
    line = await reader.readline()
    if not line:
        raise ConnectionError("redis eof")
    t = line[:1]
    if t == b"*":
        n = int(line[1:-2])
        if n < 0:
            return None
        return [await _resp_read(reader) for _ in range(n)]
    if t == b"$":
        n = int(line[1:-2])
        if n < 0:
            return None
        data = await reader.readexactly(n + 2)
        return data[:-2]
    if t == b":":
        return int(line[1:-2])
    if t in (b"+", b"-"):
        return line[1:-2]
    raise ConnectionError("bad resp")


async def redis_subscriber(hub):
    ch = events.REDIS_CHANNEL.encode()
    delay = 0.2
    while True:
        writer = None
        try:
            reader, writer = await asyncio.wait_for(
                asyncio.open_connection(config.HOST, config.REDIS_PORT, limit=64 * 1024 * 1024), 1.0
            )
            sock = writer.get_extra_info("socket")
            try:
                sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
            except Exception:
                pass
            writer.write(b"*2\r\n$9\r\nSUBSCRIBE\r\n$%d\r\n%s\r\n" % (len(ch), ch))
            await writer.drain()
            log("redis subscriber connected")
            delay = 0.2
            while True:
                msg = await _resp_read(reader)
                if isinstance(msg, list) and len(msg) == 3 and msg[0] == b"message":
                    try:
                        obj = json.loads(msg[2])
                        if "g" in obj:
                            hub.on_global(obj["g"], obj["f"])
                        else:
                            hub.on_frame(obj["f"])
                    except Exception as e:
                        log("bad redis message", e)
        except asyncio.CancelledError:
            raise
        except Exception:
            pass
        finally:
            if writer is not None:
                try:
                    writer.close()
                except Exception:
                    pass
        await asyncio.sleep(delay)
        delay = min(delay * 1.5, 1.0)


# ---------------------------------------------------------------------------------------------
# API dispatch

_api_mod = None
_api_next_try = 0.0
_api_err = None
EXECUTOR = ThreadPoolExecutor(max_workers=32, thread_name_prefix="api")


def get_api():
    global _api_mod, _api_next_try, _api_err
    if _api_mod is not None:
        return _api_mod
    now = time.time()
    if now < _api_next_try:
        return None
    try:
        import importlib
        _api_mod = importlib.import_module("huddle.api.app")
        return _api_mod
    except Exception as e:
        _api_err = f"{type(e).__name__}: {e}"
        log("cannot import huddle.api.app:", _api_err)
        _api_next_try = now + 2.0
        return None


def call_api(req):
    try:
        mod = get_api()
        if mod is None:
            if req.path.rstrip("/") == "/api/health":
                return Response(200, {"status": "ok", "node_id": NODE_ID})
            return Response(503, {"error": "api unavailable", "detail": _api_err})
        resp = mod.handle_api(req)
        if resp is None:
            return Response(404, {"error": "not found"})
        if not isinstance(resp, Response):
            if isinstance(resp, (dict, list)):
                return Response(200, resp)
            return Response(500, {"error": "bad handler response"})
        return resp
    except Exception as e:
        traceback.print_exc()
        return Response(500, {"error": "internal server error", "detail": f"{type(e).__name__}: {e}"})


# ---------------------------------------------------------------------------------------------
# static files

def serve_static(path, method):
    root = os.path.realpath(config.STATIC_DIR)
    if path.startswith("/static/"):
        rel = path[len("/static/"):]
        full = os.path.realpath(os.path.join(root, rel))
        if not full.startswith(root + os.sep) or not os.path.isfile(full):
            return Response(404, "not found")
    else:
        full = os.path.join(root, "index.html")
        if not os.path.isfile(full):
            return Response(404, "<!doctype html><title>Huddle</title><p>UI not built yet</p>",
                            content_type="text/html; charset=utf-8")
    ext = os.path.splitext(full)[1].lower()
    ctype = CONTENT_TYPES.get(ext) or mimetypes.guess_type(full)[0] or "application/octet-stream"
    try:
        with open(full, "rb") as f:
            data = f.read()
    except OSError:
        return Response(404, "not found")
    return Response(200, data, content_type=ctype, headers={
        "Cache-Control": "no-cache, no-store, must-revalidate", "Pragma": "no-cache", "Expires": "0"})


# ---------------------------------------------------------------------------------------------
# HTTP server

def build_response(resp: Response, keep_alive: bool, head=False) -> bytes:
    status = int(resp.status)
    reason = REASONS.get(status, "Status")
    body = resp.body or b""
    lines = [f"HTTP/1.1 {status} {reason}\r\n".encode()]
    hdrs = {k.lower(): (k, v) for k, v in resp.headers.items()}
    if resp.content_type and "content-type" not in hdrs:
        lines.append(f"Content-Type: {resp.content_type}\r\n".encode())
    for lk, (k, v) in hdrs.items():
        if lk in ("content-length", "connection", "transfer-encoding"):
            continue
        lines.append(f"{k}: {v}\r\n".encode("latin-1", "replace"))
    if status not in (204, 304) or body:
        lines.append(b"Content-Length: %d\r\n" % len(body))
    lines.append(b"Connection: keep-alive\r\n" if keep_alive else b"Connection: close\r\n")
    if "access-control-allow-origin" not in hdrs:
        lines.append(CORS)
    lines.append(b"\r\n")
    out = b"".join(lines)
    if not head and status not in (204, 304):
        out += body
    return out


async def read_body(reader, writer, headers):
    te = headers.get("transfer-encoding", "").lower()
    if "chunked" in te:
        if headers.get("expect", "").lower() == "100-continue":
            writer.write(b"HTTP/1.1 100 Continue\r\n\r\n")
        body = bytearray()
        while True:
            line = await reader.readline()
            if not line:
                raise ConnectionError("eof in chunked body")
            size = int(line.split(b";")[0].strip() or b"0", 16)
            if size == 0:
                while True:
                    t = await reader.readline()
                    if t in (b"\r\n", b"\n", b""):
                        break
                break
            if len(body) + size > MAX_BODY:
                return None
            body += await reader.readexactly(size)
            await reader.readexactly(2)
        return bytes(body)
    cl = headers.get("content-length")
    if not cl:
        return b""
    n = int(cl)
    if n < 0:
        raise ValueError("bad content-length")
    if n > MAX_BODY:
        return None
    if headers.get("expect", "").lower() == "100-continue":
        writer.write(b"HTTP/1.1 100 Continue\r\n\r\n")
    return await reader.readexactly(n) if n else b""


async def handle_conn(reader, writer):
    loop = asyncio.get_running_loop()
    sock = writer.get_extra_info("socket")
    try:
        sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
    except Exception:
        pass
    try:
        while True:
            try:
                line = await reader.readline()
            except (asyncio.LimitOverrunError, ValueError):
                writer.write(build_response(Response(431, {"error": "request line too long"}), False))
                break
            if not line:
                break
            if line in (b"\r\n", b"\n"):
                continue
            parts = line.decode("latin-1").strip().split()
            if len(parts) != 3:
                writer.write(build_response(Response(400, {"error": "bad request"}), False))
                break
            method, target, version = parts
            headers = {}
            nhdr = 0
            while True:
                h = await reader.readline()
                if not h:
                    return
                if h in (b"\r\n", b"\n"):
                    break
                nhdr += 1
                if nhdr > 200:
                    writer.write(build_response(Response(431, {"error": "too many headers"}), False))
                    return
                k, _, v = h.decode("latin-1").partition(":")
                headers[k.strip().lower()] = v.strip()
            conn_hdr = headers.get("connection", "").lower()
            keep_alive = (version == "HTTP/1.1" and "close" not in conn_hdr) or \
                         (version == "HTTP/1.0" and "keep-alive" in conn_hdr)
            raw_path, _, qs = target.partition("?")
            if raw_path.startswith("http://") or raw_path.startswith("https://"):
                raw_path = "/" + raw_path.split("/", 3)[-1] if raw_path.count("/") >= 3 else "/"
            path = unquote(raw_path)
            query = {}
            for k, v in parse_qsl(qs, keep_blank_values=True):
                query.setdefault(k, v)

            if path.rstrip("/") == "/api/ws":
                if "websocket" in headers.get("upgrade", "").lower():
                    await handle_ws(reader, writer, headers, query)
                    return
                writer.write(build_response(Response(426, {"error": "websocket upgrade required"}), keep_alive))
                if not keep_alive:
                    break
                continue

            try:
                body = await read_body(reader, writer, headers)
            except (ValueError, asyncio.IncompleteReadError, ConnectionError):
                writer.write(build_response(Response(400, {"error": "bad body"}), False))
                break
            if body is None:
                writer.write(build_response(Response(413, {"error": "payload too large"}), False))
                await writer.drain()
                break

            method = method.upper()
            if method == "OPTIONS":
                resp = Response(204)
            elif path.startswith("/api/") or path == "/api":
                req = Request(method=method, path=path, query=query, headers=headers, body=body,
                              node_id=NODE_ID)
                resp = await loop.run_in_executor(EXECUTOR, call_api, req)
            elif method in ("GET", "HEAD"):
                resp = serve_static(path, method)
            else:
                resp = Response(405, {"error": "method not allowed"})
            writer.write(build_response(resp, keep_alive, head=(method == "HEAD")))
            if writer.transport.get_write_buffer_size() > 256 * 1024:
                await writer.drain()
            if not keep_alive:
                break
    except (ConnectionError, asyncio.IncompleteReadError, OSError):
        pass
    except Exception:
        traceback.print_exc()
    finally:
        try:
            await writer.drain()
        except Exception:
            pass
        try:
            writer.close()
        except Exception:
            pass


# ---------------------------------------------------------------------------------------------
# WebSocket endpoint

def auth_token(token):
    if not token:
        return None
    rows = HUB.q("SELECT user_id FROM tokens WHERE token=?", (token,))
    if not rows:
        return None
    return int(rows[0][0])


def can_access(user_id, ch):
    rows = HUB.q("SELECT is_private, is_dm FROM channels WHERE id=?", (ch,))
    if not rows:
        return "not_found"
    is_private, is_dm = rows[0]
    if not is_private and not is_dm:
        return None
    m = HUB.q("SELECT 1 FROM channel_members WHERE channel_id=? AND user_id=? LIMIT 1", (ch, user_id))
    return None if m else "forbidden"


async def handle_ws(reader, writer, headers, query):
    token = query.get("token") or ""
    if not token:
        auth = headers.get("authorization", "")
        if auth.lower().startswith("bearer "):
            token = auth[7:].strip()
    try:
        user_id = auth_token(token)
    except Exception as e:
        log("ws auth db error", e)
        writer.write(build_response(Response(503, {"error": "unavailable"}), False))
        await writer.drain()
        writer.close()
        return
    if user_id is None:
        writer.write(build_response(Response(401, {"error": "invalid token"}), False))
        await writer.drain()
        writer.close()
        return
    key = headers.get("sec-websocket-key", "")
    if not key:
        writer.write(build_response(Response(400, {"error": "missing Sec-WebSocket-Key"}), False))
        await writer.drain()
        writer.close()
        return
    accept = base64.b64encode(hashlib.sha1((key + WS_GUID).encode()).digest()).decode()
    resp = ("HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"
            f"Sec-WebSocket-Accept: {accept}\r\n")
    proto = headers.get("sec-websocket-protocol")
    if proto:
        resp += f"Sec-WebSocket-Protocol: {proto.split(',')[0].strip()}\r\n"
    writer.write((resp + "\r\n").encode())

    conn = WSConn(HUB, user_id, writer)
    HUB.add_conn(conn)
    frags = []
    frag_op = None
    close_code = 1000
    try:
        while True:
            h = await reader.readexactly(2)
            fin = h[0] & 0x80
            op = h[0] & 0x0F
            masked = h[1] & 0x80
            ln = h[1] & 0x7F
            if ln == 126:
                ln = struct.unpack(">H", await reader.readexactly(2))[0]
            elif ln == 127:
                ln = struct.unpack(">Q", await reader.readexactly(8))[0]
            if ln > MAX_WS_MESSAGE:
                close_code = 1009
                break
            mask = await reader.readexactly(4) if masked else None
            data = await reader.readexactly(ln) if ln else b""
            if mask:
                data = unmask(data, mask)
            if op == 0x8:  # close
                code = struct.unpack(">H", data[:2])[0] if len(data) >= 2 else 1000
                conn.write(ws_frame(0x8, struct.pack(">H", code if code not in (1005, 1006) else 1000)))
                close_code = None
                break
            if op == 0x9:  # ping
                conn.write(ws_frame(0xA, data))
                continue
            if op == 0xA:  # pong
                continue
            if op in (0x1, 0x2):
                if frag_op is not None:
                    close_code = 1002
                    break
                if fin:
                    if op == 0x1:
                        handle_ws_message(conn, data)
                    continue
                frag_op = op
                frags = [data]
                continue
            if op == 0x0:
                if frag_op is None:
                    close_code = 1002
                    break
                frags.append(data)
                if sum(len(f) for f in frags) > MAX_WS_MESSAGE:
                    close_code = 1009
                    break
                if fin:
                    msg = b"".join(frags)
                    op0 = frag_op
                    frag_op, frags = None, []
                    if op0 == 0x1:
                        handle_ws_message(conn, msg)
                continue
            close_code = 1002
            break
        if close_code:
            conn.write(ws_frame(0x8, struct.pack(">H", close_code)))
    except (asyncio.IncompleteReadError, ConnectionError, OSError):
        pass
    except Exception:
        traceback.print_exc()
    finally:
        HUB.remove_conn(conn)
        try:
            await asyncio.wait_for(writer.drain(), 2)
        except Exception:
            pass
        try:
            writer.close()
        except Exception:
            pass


def _int(v):
    if isinstance(v, bool):
        raise ValueError
    return int(v)


def handle_ws_message(conn, data):
    try:
        msg = json.loads(data.decode("utf-8"))
        if not isinstance(msg, dict):
            raise ValueError
    except Exception:
        conn.send({"type": "error", "error": "invalid_json"})
        return
    t = msg.get("type")
    try:
        if t == "ping":
            out = {"type": "pong"}
            if "id" in msg:
                out["id"] = msg["id"]
            conn.send(out)
        elif t in ("subscribe", "resume"):
            try:
                ch = _int(msg.get("channel_id"))
            except Exception:
                conn.send({"type": "error", "error": "invalid_channel_id", "request": t})
                return
            err = can_access(conn.user_id, ch)
            if err:
                conn.send({"type": "error", "error": err, "channel_id": ch, "request": t})
                return
            if t == "subscribe":
                head = HUB.head(ch)
                HUB.subscribe(conn, ch, head)
                conn.send({"type": "subscribed", "channel_id": ch, "head_seq": head})
            else:
                try:
                    since = _int(msg.get("since_seq", 0) or 0)
                except Exception:
                    conn.send({"type": "error", "error": "invalid_since_seq", "channel_id": ch})
                    return
                rows = HUB.q("SELECT seq, payload FROM channel_events WHERE channel_id=? AND seq>? ORDER BY seq",
                             (ch, max(since, 0)))
                head = rows[-1][0] if rows else HUB.head(ch)
                if since > 0 and rows:
                    earliest = int(HUB.q("SELECT MIN(seq) FROM channel_events WHERE channel_id=?", (ch,))[0][0] or 1)
                    if since < earliest - 1:
                        conn.send({"type": "resume.gap", "channel_id": ch, "earliest_seq": earliest})
                if rows:
                    conn.write(b"".join(ws_frame(0x1, p.encode("utf-8")) for _s, p in rows))
                # last sent = max(already-sent, replayed head)
                HUB.subscribe(conn, ch, head)
                conn.send({"type": "resumed", "channel_id": ch, "head_seq": max(head, conn.subs.get(ch, 0))})
        elif t == "unsubscribe":
            try:
                ch = _int(msg.get("channel_id"))
            except Exception:
                return
            HUB._unsub(conn, ch)
            conn.send({"type": "unsubscribed", "channel_id": ch})
        else:
            conn.send({"type": "error", "error": "unknown_type", "request": t})
    except Exception as e:
        log("ws message error", e)
        conn.send({"type": "error", "error": "internal_error"})


# ---------------------------------------------------------------------------------------------

async def amain():
    global HUB
    loop = asyncio.get_running_loop()
    HUB = Hub(loop)

    # schema (retry: other nodes may hold the write lock at startup)
    for _ in range(100):
        try:
            db = config.connect()
            events.ensure_schema(db)
            db.close()
            break
        except Exception as e:
            log("schema init retry", e)
            await asyncio.sleep(0.1)

    def hook(kind, frame, uid):
        loop.call_soon_threadsafe(HUB.on_local, kind, frame, uid)

    events._local_hook = hook
    events._local_online = lambda: HUB.online
    events._local_node_id = NODE_ID

    threading.Thread(target=tail_thread, args=(loop, HUB), daemon=True, name="tail").start()
    threading.Thread(target=presence_thread, args=(HUB,), daemon=True, name="presence").start()
    loop.create_task(redis_subscriber(HUB))
    # warm the API import off the loop so the first request is fast
    loop.run_in_executor(EXECUTOR, get_api)

    port = config.BASE_PORT + NODE_ID
    last = None
    for _ in range(200):
        try:
            server = await asyncio.start_server(handle_conn, config.HOST, port, reuse_address=True,
                                                limit=1024 * 1024, backlog=1024)
            break
        except OSError as e:
            last = e
            await asyncio.sleep(0.1)
    else:
        raise last
    log(f"listening on {config.HOST}:{port}")
    async with server:
        await server.serve_forever()


def main(argv=None):
    global NODE_ID
    ap = argparse.ArgumentParser()
    ap.add_argument("--node-id", type=int, default=int(os.environ.get("HUDDLE_NODE_ID", "0")))
    args = ap.parse_args(argv)
    NODE_ID = args.node_id
    try:
        asyncio.run(amain())
    except KeyboardInterrupt:
        pass


if __name__ == "__main__":
    main()

