"""Huddle REST API. Entry point: handle_api(req) -> Response (synchronous, thread-safe)."""
import hashlib
import hmac
import json
import mimetypes
import os
import re
import secrets
import sqlite3
import sys
import time
import traceback
import urllib.parse
from zoneinfo import ZoneInfo

from huddle import config, events
from huddle.web.http import Request, Response  # noqa: F401
from huddle.api import db as dbm
from huddle.api.db import now_iso, epoch_iso, tx, emit

PBKDF2_ITERS = 50_000
USERNAME_RE = re.compile(r"^[A-Za-z0-9_]{1,64}$")
SLUG_RE = re.compile(r"^[a-z0-9-]{2,32}$")
CHANNEL_RE = re.compile(r"^[a-z0-9][a-z0-9_-]{0,31}$")
HANDLE_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_-]{0,31}$")
ROLES = ("owner", "admin", "member", "guest")
JOIN_MODES = ("open", "invite_only")
MAX_BODY = 40000
SHRUG = "¯\\_(ツ)_/¯"
MENTION_RE = re.compile(r"(?<![\w.+\-@/])@([A-Za-z0-9_][A-Za-z0-9_-]*)")
SPECIAL_ALL = ("channel", "everyone")


class ApiError(Exception):
    def __init__(self, status, message):
        super().__init__(message)
        self.status = status
        self.message = message


def fail(status, message):
    raise ApiError(status, message)


def ok(body, status=200):
    return Response(status, body)


# ---------------------------------------------------------------------------------------------
# routing

ROUTES = []


def route(method, pattern, auth=True):
    rx = re.compile("^" + pattern + "$")

    def deco(fn):
        ROUTES.append((method, rx, fn, auth))
        return fn
    return deco


class Ctx:
    def __init__(self, req):
        self.req = req
        self.c = dbm.conn()
        self.user = None
        self.uid = None
        self._body = None

    def body(self):
        if self._body is None:
            try:
                data = self.req.json()
            except ValueError:
                fail(400, "invalid JSON body")
            if data is None:
                data = {}
            if not isinstance(data, dict):
                fail(400, "JSON body must be an object")
            self._body = data
        return self._body


def _authenticate(ctx):
    req = ctx.req
    auth = req.headers.get("authorization", "")
    token = None
    if auth[:7].lower() == "bearer ":
        token = auth[7:].strip()
    elif auth and " " not in auth.strip():
        token = auth.strip()
    if not token:
        token = req.query.get("token")
    if not token:
        fail(401, "authentication required")
    row = ctx.c.execute(
        "SELECT u.* FROM tokens t JOIN users u ON u.id=t.user_id WHERE t.token=?", (token,)
    ).fetchone()
    if row is None:
        fail(401, "invalid token")
    ctx.user = row
    ctx.uid = row["id"]
    ctx.token = token


def handle_api(req):
    try:
        dbm.ensure_schema()
        path = req.path
        if len(path) > 1 and path.endswith("/"):
            path = path.rstrip("/")
        path_matched = False
        for method, rx, fn, auth in ROUTES:
            m = rx.match(path)
            if not m:
                continue
            path_matched = True
            if method != req.method:
                continue
            ctx = Ctx(req)
            if auth:
                _authenticate(ctx)
            return fn(ctx, **m.groupdict())
        if path_matched:
            return Response(405, {"error": "method not allowed"})
        return Response(404, {"error": "not found"})
    except ApiError as e:
        return Response(e.status, {"error": e.message})
    except sqlite3.IntegrityError as e:
        return Response(409, {"error": "conflict: %s" % e})
    except sqlite3.OperationalError as e:
        traceback.print_exc(file=sys.stderr)
        if "locked" not in str(e).lower():
            dbm.reset_conn()
        return Response(503, {"error": "database busy"})
    except Exception as e:  # pragma: no cover
        traceback.print_exc(file=sys.stderr)
        return Response(500, {"error": "internal error: %s" % e})


# ---------------------------------------------------------------------------------------------
# validation helpers

def _int(v, name):
    if isinstance(v, bool):
        fail(400, "%s must be an integer" % name)
    if isinstance(v, int):
        return v
    if isinstance(v, str) and re.fullmatch(r"-?\d+", v.strip() or "x"):
        return int(v.strip())
    fail(400, "%s must be an integer" % name)


def _str(data, key, required=False, max_len=None, min_len=0, allow_none=False):
    if key not in data:
        if required:
            fail(400, "%s is required" % key)
        return None
    v = data[key]
    if v is None:
        if allow_none:
            return ""
        fail(400, "%s must be a string" % key)
    if not isinstance(v, str):
        fail(400, "%s must be a string" % key)
    if max_len is not None and len(v) > max_len:
        fail(400, "%s is too long (max %d)" % (key, max_len))
    if len(v) < min_len:
        fail(400, "%s is too short" % key)
    return v


def _limit(ctx, default=50, maximum=200):
    v = ctx.req.query.get("limit")
    if v is None or v == "":
        return default
    try:
        n = int(v)
    except ValueError:
        fail(400, "limit must be an integer")
    if n < 1:
        fail(400, "limit must be positive")
    return min(n, maximum)


def _truthy(v):
    return str(v or "").lower() in ("1", "true", "yes", "on")


# ---------------------------------------------------------------------------------------------
# object builders

def user_obj(row):
    if row is None:
        return None
    return {
        "id": row["id"],
        "username": row["username"],
        "display_name": row["display_name"] or row["username"],
        "timezone": row["timezone"],
        "avatar_url": row["avatar_url"],
        "status_text": row["status_text"],
        "status_emoji": row["status_emoji"],
        "created_at": row["created_at"],
    }


def get_user_row(c, uid):
    return c.execute("SELECT * FROM users WHERE id=?", (uid,)).fetchone()


def user_by_id(c, uid, cache=None):
    if cache is not None and uid in cache:
        return cache[uid]
    u = user_obj(get_user_row(c, uid))
    if cache is not None:
        cache[uid] = u
    return u


def ws_obj(row, role=None):
    d = {
        "id": row["id"],
        "slug": row["slug"],
        "name": row["name"],
        "owner_id": row["owner_id"],
        "join_mode": row["join_mode"],
        "created_at": row["created_at"],
    }
    if role is not None:
        d["my_role"] = role
    return d


def channel_obj(c, row, uid=None):
    d = {
        "id": row["id"],
        "workspace_id": row["workspace_id"],
        "name": row["name"],
        "is_private": bool(row["is_private"]),
        "is_dm": bool(row["is_dm"]),
        "topic": row["topic"] or "",
        "is_archived": bool(row["is_archived"]),
        "created_by": row["created_by"],
        "created_at": row["created_at"],
    }
    d["member_count"] = c.execute(
        "SELECT COUNT(*) FROM channel_members WHERE channel_id=?", (row["id"],)).fetchone()[0]
    if uid is not None:
        d["is_member"] = is_channel_member(c, row["id"], uid)
    return d


def file_obj(row):
    return {
        "id": row["id"],
        "uploader_id": row["uploader_id"],
        "filename": row["filename"],
        "content_type": row["content_type"],
        "size": row["size"],
        "created_at": row["created_at"],
        "message_id": row["message_id"],
        "url": "/api/files/%d/download" % row["id"],
    }


def reactions_for(c, mid):
    out = []
    idx = {}
    for r in c.execute(
            "SELECT emoji, user_id FROM reactions WHERE message_id=? ORDER BY created_at, rowid", (mid,)):
        e = r["emoji"]
        if e not in idx:
            idx[e] = {"emoji": e, "count": 0, "user_ids": []}
            out.append(idx[e])
        idx[e]["count"] += 1
        idx[e]["user_ids"].append(r["user_id"])
    return out


def reply_count(c, mid):
    return c.execute(
        "SELECT COUNT(*) FROM messages WHERE parent_id=? AND deleted_at IS NULL", (mid,)).fetchone()[0]


def message_obj(c, row, cache=None):
    mid = row["id"]
    d = {
        "id": mid,
        "channel_id": row["channel_id"],
        "author_id": row["author_id"],
        "author": user_by_id(c, row["author_id"], cache),
        "body": row["body"],
        "parent_id": row["parent_id"],
        "reply_count": 0,
        "created_at": row["created_at"],
        "edited_at": row["edited_at"],
        "is_deleted": row["deleted_at"] is not None,
        "files": [file_obj(f) for f in c.execute(
            "SELECT * FROM files WHERE message_id=? ORDER BY id", (mid,))],
        "reactions": reactions_for(c, mid),
        "mentions": [r[0] for r in c.execute(
            "SELECT user_id FROM message_mentions WHERE message_id=? ORDER BY rowid", (mid,))],
        "seq": row["seq"],
        "blocks": json.loads(row["blocks"]) if row["blocks"] else None,
    }
    if row["parent_id"] is None:
        r = c.execute(
            "SELECT COUNT(*), MAX(created_at) FROM messages WHERE parent_id=? AND deleted_at IS NULL",
            (mid,)).fetchone()
        d["reply_count"] = r[0]
        d["last_reply_at"] = r[1]
    d["is_pinned"] = c.execute("SELECT 1 FROM pins WHERE message_id=?", (mid,)).fetchone() is not None
    return d


def member_obj(c, row):
    return {
        "user_id": row["user_id"],
        "workspace_id": row["workspace_id"],
        "role": row["role"],
        "joined_at": row["joined_at"],
        "user": user_by_id(c, row["user_id"]),
    }


def invitation_obj(c, row):
    ws = c.execute("SELECT slug FROM workspaces WHERE id=?", (row["workspace_id"],)).fetchone()
    exhausted = row["uses"] >= row["max_uses"]
    expired = row["expires_at"] is not None and row["expires_at"] <= time.time()
    return {
        "id": row["id"],
        "code": row["code"],
        "workspace_id": row["workspace_id"],
        "workspace_slug": ws["slug"] if ws else None,
        "created_by": row["created_by"],
        "invited_user_id": row["invited_user_id"],
        "role": row["role"],
        "max_uses": row["max_uses"],
        "uses": row["uses"],
        "expires_at": epoch_iso(row["expires_at"]),
        "revoked": bool(row["revoked"]),
        "active": not (row["revoked"] or exhausted or expired),
        "created_at": row["created_at"],
    }


def group_obj(c, row):
    return {
        "id": row["id"],
        "workspace_id": row["workspace_id"],
        "handle": row["handle"],
        "name": row["name"],
        "created_by": row["created_by"],
        "created_at": row["created_at"],
        "member_user_ids": [r[0] for r in c.execute(
            "SELECT user_id FROM user_group_members WHERE group_id=? ORDER BY user_id", (row["id"],))],
    }


# ---------------------------------------------------------------------------------------------
# lookup / permission helpers

def get_ws(c, slug):
    row = c.execute("SELECT * FROM workspaces WHERE slug=?", (slug,)).fetchone()
    if row is None and slug.isdigit():
        row = c.execute("SELECT * FROM workspaces WHERE id=?", (int(slug),)).fetchone()
    if row is None:
        fail(404, "workspace not found")
    return row


def ws_role(c, ws_id, uid):
    if ws_id is None:
        return None
    r = c.execute("SELECT role FROM workspace_members WHERE workspace_id=? AND user_id=?",
                  (ws_id, uid)).fetchone()
    return r[0] if r else None


def require_ws_member(c, ws, uid):
    role = ws_role(c, ws["id"], uid)
    if role is None:
        if ws["owner_id"] == uid:
            return "owner"
        fail(403, "not a member of this workspace")
    return role


def require_ws_admin(c, ws, uid):
    role = require_ws_member(c, ws, uid)
    if role not in ("owner", "admin"):
        fail(403, "admin or owner required")
    return role


def get_channel(c, cid):
    row = c.execute("SELECT * FROM channels WHERE id=?", (int(cid),)).fetchone()
    if row is None:
        fail(404, "channel not found")
    return row


def is_channel_member(c, cid, uid):
    return c.execute("SELECT 1 FROM channel_members WHERE channel_id=? AND user_id=?",
                     (cid, uid)).fetchone() is not None


def can_read_channel(c, ch, uid):
    if is_channel_member(c, ch["id"], uid):
        return True
    if ch["is_dm"] or ch["is_private"]:
        return False
    role = ws_role(c, ch["workspace_id"], uid)
    return role is not None and role != "guest"


def require_channel_access(c, ch, uid):
    if not can_read_channel(c, ch, uid):
        fail(403, "no access to this channel")


def require_not_archived(ch):
    if ch["is_archived"]:
        fail(423, "channel is archived")


def is_ws_owner(c, ws_id, uid):
    if ws_id is None:
        return False
    r = c.execute("SELECT owner_id FROM workspaces WHERE id=?", (ws_id,)).fetchone()
    return (r is not None and r[0] == uid) or ws_role(c, ws_id, uid) == "owner"


def get_message(c, mid, allow_deleted=False):
    row = c.execute("SELECT * FROM messages WHERE id=?", (int(mid),)).fetchone()
    if row is None or (row["deleted_at"] is not None and not allow_deleted):
        fail(404, "message not found")
    return row


def general_channel_id(c, ws_id):
    r = c.execute("SELECT id FROM channels WHERE workspace_id=? AND name='general' AND is_dm=0",
                  (ws_id,)).fetchone()
    return r[0] if r else None


def add_channel_member(c, frames, cid, uid, emit_event=True):
    cur = c.execute("INSERT OR IGNORE INTO channel_members(channel_id,user_id,joined_at) VALUES(?,?,?)",
                    (cid, uid, now_iso()))
    if cur.rowcount == 1 and emit_event:
        emit(c, frames, cid, "member.joined", {"user_id": uid, "user": user_by_id(c, uid)})
    return cur.rowcount == 1


def add_ws_member(c, frames, ws_id, uid, role="member", join_general=True):
    cur = c.execute(
        "INSERT OR IGNORE INTO workspace_members(workspace_id,user_id,role,joined_at) VALUES(?,?,?,?)",
        (ws_id, uid, role, now_iso()))
    added = cur.rowcount == 1
    if added and join_general:
        gid = general_channel_id(c, ws_id)
        if gid is not None:
            g = c.execute("SELECT is_archived FROM channels WHERE id=?", (gid,)).fetchone()
            if g and not g[0]:
                add_channel_member(c, frames, gid, uid)
    return added


def last_read(c, uid, cid):
    r = c.execute("SELECT last_read_seq FROM read_state WHERE user_id=? AND channel_id=?",
                  (uid, cid)).fetchone()
    return r[0] if r else 0


def read_state_obj(c, uid, cid):
    lr = last_read(c, uid, cid)
    unread = c.execute(
        "SELECT COUNT(*) FROM messages WHERE channel_id=? AND seq>? AND author_id<>? AND deleted_at IS NULL",
        (cid, lr, uid)).fetchone()[0]
    mentions = c.execute(
        "SELECT COUNT(*) FROM message_mentions mm JOIN messages m ON m.id=mm.message_id "
        "WHERE m.channel_id=? AND mm.user_id=? AND m.seq>? AND m.deleted_at IS NULL AND m.author_id<>?",
        (cid, uid, lr, uid)).fetchone()[0]
    return {"channel_id": cid, "last_read_seq": lr, "unread_count": unread, "mention_count": mentions,
            "head_seq": events.head_seq(c, cid)}


# ---------------------------------------------------------------------------------------------
# passwords / tokens

def hash_password(pw, salt):
    return hashlib.pbkdf2_hmac("sha256", pw.encode("utf-8"), bytes.fromhex(salt), PBKDF2_ITERS).hex()


def issue_token(c, uid):
    tok = secrets.token_hex(24)
    c.execute("INSERT INTO tokens(token,user_id,created_at) VALUES(?,?,?)", (tok, uid, now_iso()))
    return tok


# ---------------------------------------------------------------------------------------------
# health / auth

@route("GET", r"/api/health", auth=False)
def health(ctx):
    return ok({"status": "ok", "node_id": int(ctx.req.node_id)})


@route("POST", r"/api/auth/register", auth=False)
def register(ctx):
    data = ctx.body()
    username = data.get("username")
    password = data.get("password")
    if not isinstance(username, str) or not USERNAME_RE.match(username):
        fail(400, "username must be 1-64 letters, digits or underscores")
    if not isinstance(password, str) or len(password) < 8:
        fail(400, "password must be at least 8 characters")
    if len(password) > 1024:
        fail(400, "password too long")
    display_name = data.get("display_name")
    if display_name is None or (isinstance(display_name, str) and not display_name.strip()):
        display_name = username
    if not isinstance(display_name, str) or len(display_name) > 80:
        fail(400, "display_name must be a string up to 80 chars")
    display_name = display_name.strip()
    c = ctx.c
    if c.execute("SELECT 1 FROM users WHERE username=?", (username,)).fetchone():
        fail(409, "username already taken")
    salt = secrets.token_hex(16)
    ph = hash_password(password, salt)

    def work(c, frames):
        if c.execute("SELECT 1 FROM users WHERE username=?", (username,)).fetchone():
            fail(409, "username already taken")
        cur = c.execute(
            "INSERT INTO users(username,password_hash,salt,display_name,created_at) VALUES(?,?,?,?,?)",
            (username, ph, salt, display_name, now_iso()))
        uid = cur.lastrowid
        return uid, issue_token(c, uid)
    uid, tok = tx(work)
    return ok({"user": user_obj(get_user_row(ctx.c, uid)), "token": tok}, 201)


@route("POST", r"/api/auth/login", auth=False)
def login(ctx):
    data = ctx.body()
    username = data.get("username")
    password = data.get("password")
    if not isinstance(username, str) or not isinstance(password, str) or not username:
        fail(400, "username and password are required")
