@route("PATCH", r"/api/users/me")
def users_patch(ctx):
    data = ctx.body()
    updates = {}
    if "display_name" in data:
        v = _str(data, "display_name", max_len=80)
        if not v.strip():
            fail(400, "display_name cannot be empty")
        updates["display_name"] = v.strip()
    if "timezone" in data:
        v = _str(data, "timezone", max_len=64)
        try:
            if not v or v != v.strip():
                raise ValueError
            ZoneInfo(v)
        except Exception:
            fail(400, "invalid timezone")
        updates["timezone"] = v
    if "avatar_url" in data:
        updates["avatar_url"] = _str(data, "avatar_url", max_len=2048, allow_none=True)
    if "status_text" in data:
        updates["status_text"] = _str(data, "status_text", max_len=100, allow_none=True)
    if "status_emoji" in data:
        updates["status_emoji"] = _str(data, "status_emoji", max_len=64, allow_none=True)
    if updates:
        sets = ", ".join("%s=?" % k for k in updates)
        ctx.c.execute("UPDATE users SET %s WHERE id=?" % sets, (*updates.values(), ctx.uid))
    u = user_obj(get_user_row(ctx.c, ctx.uid))
    if updates:
        try:
            events.publish_global({"type": "user.updated", "user": u})
        except Exception:
            pass
    return ok({"user": u})


