@route("POST", r"/api/workspaces")
def ws_create(ctx):
    data = ctx.body()
    slug = data.get("slug")
    if not isinstance(slug, str) or not SLUG_RE.match(slug):
        fail(400, "slug must match ^[a-z0-9-]{2,32}$")
    name = data.get("name")
    if name is None:
        name = slug
    if not isinstance(name, str) or not name.strip() or len(name) > 80:
        fail(400, "name must be a non-empty string up to 80 chars")
    name = name.strip()
    join_mode = data.get("join_mode", "open")
    if join_mode not in JOIN_MODES:
        fail(400, "join_mode must be open or invite_only")
    uid = ctx.uid

    def work(c, frames):
        if c.execute("SELECT 1 FROM workspaces WHERE slug=?", (slug,)).fetchone():
            fail(409, "slug already taken")
        now = now_iso()
        wid = c.execute("INSERT INTO workspaces(slug,name,owner_id,join_mode,created_at) VALUES(?,?,?,?,?)",
                        (slug, name, uid, join_mode, now)).lastrowid
        c.execute("INSERT INTO workspace_members(workspace_id,user_id,role,joined_at) VALUES(?,?,?,?)",
                  (wid, uid, "owner", now))
        gid = c.execute("INSERT INTO channels(workspace_id,name,is_private,is_dm,topic,created_by,created_at) "
                        "VALUES(?,?,0,0,'',?,?)", (wid, "general", uid, now)).lastrowid
        c.execute("INSERT INTO channel_members(channel_id,user_id,joined_at) VALUES(?,?,?)", (gid, uid, now))
        return wid, gid
    wid, gid = tx(work)
    c = ctx.c
    ws = c.execute("SELECT * FROM workspaces WHERE id=?", (wid,)).fetchone()
    ch = get_channel(c, gid)
    return ok({"workspace": ws_obj(ws, "owner"), "general_channel": channel_obj(c, ch, uid)}, 201)


