        (ctx.uid, ctx.uid)).fetchall()
    return ok({"workspaces": [ws_obj(r, r["my_role"] or "owner") for r in rows]})


def _visible_channels(c, ws, uid, role, include_archived=False, include_private=False):
    rows = c.execute("SELECT * FROM channels WHERE workspace_id=? AND is_dm=0 ORDER BY name",
                     (ws["id"],)).fetchall()
    out = []
    for r in rows:
        if r["is_archived"] and not include_archived:
            continue
        if r["is_private"] and not is_channel_member(c, r["id"], uid):
            if not (include_private and role in ("owner", "admin")):
                continue
        out.append(r)
    return out


def _dm_obj(c, row, uid):
    d = channel_obj(c, row, uid)
    other = c.execute("SELECT user_id FROM channel_members WHERE channel_id=? AND user_id<>? LIMIT 1",
                      (row["id"], uid)).fetchone()
    d["other_user"] = user_by_id(c, other[0] if other else uid)
    d["read_state"] = read_state_obj(c, uid, row["id"])
    return d


@route("GET", r"/api/workspaces/(?P<slug>[^/]+)")
def ws_detail(ctx, slug):
    c = ctx.c
    ws = get_ws(c, slug)
    role = ws_role(c, ws["id"], ctx.uid)
    if role is None and ws["owner_id"] == ctx.uid:
        role = "owner"
    if role is None and ws["join_mode"] != "open":
        fail(403, "not a member of this workspace")
    q = ctx.req.query
    rows = _visible_channels(c, ws, ctx.uid, role, _truthy(q.get("include_archived")),
                             _truthy(q.get("include_private")))
    channels = []
    read_states = []
    for r in rows:
        d = channel_obj(c, r, ctx.uid)
        rs = read_state_obj(c, ctx.uid, r["id"])
        d["read_state"] = rs
        d["unread_count"] = rs["unread_count"]
        d["mention_count"] = rs["mention_count"]
        d["last_read_seq"] = rs["last_read_seq"]
        channels.append(d)
        read_states.append(rs)
    dms = []
    if role is not None:
        for r in c.execute(
                "SELECT ch.* FROM channels ch JOIN channel_members cm ON cm.channel_id=ch.id "
                "WHERE cm.user_id=? AND ch.is_dm=1 AND (ch.workspace_id=? OR ch.workspace_id IS NULL) "
                "ORDER BY ch.id", (ctx.uid, ws["id"])).fetchall():
            dms.append(_dm_obj(c, r, ctx.uid))
    return ok({"workspace": ws_obj(ws, role), "channels": channels, "read_state": read_states,
               "dms": dms, "my_role": role})


