@route("PATCH", r"/api/workspaces/(?P<slug>[^/]+)/members/(?P<target>\d+)")
def ws_member_patch(ctx, slug, target):
    c = ctx.c
    ws = get_ws(c, slug)
    caller_role = require_ws_member(c, ws, ctx.uid)
    target = int(target)
    data = ctx.body()
    new_role = data.get("role")
    if new_role not in ROLES:
        fail(400, "role must be one of owner, admin, member, guest")
    if new_role == "owner":
        fail(400, "use transfer_ownership to change the owner")
    if caller_role not in ("owner", "admin"):
        fail(403, "admin or owner required")
    trow = c.execute("SELECT * FROM workspace_members WHERE workspace_id=? AND user_id=?",
                     (ws["id"], target)).fetchone()
    if trow is None:
        fail(404, "user is not a member of this workspace")
    if trow["role"] == "owner" or target == ws["owner_id"]:
        fail(403, "the owner's role cannot be changed")
    if caller_role == "admin" and trow["role"] == "admin" and target != ctx.uid:
        fail(403, "admins cannot modify other admins")
    c.execute("UPDATE workspace_members SET role=? WHERE workspace_id=? AND user_id=?",
              (new_role, ws["id"], target))
    trow = c.execute("SELECT * FROM workspace_members WHERE workspace_id=? AND user_id=?",
                     (ws["id"], target)).fetchone()
    return ok({"member": member_obj(c, trow)})


@route("DELETE", r"/api/workspaces/(?P<slug>[^/]+)/members/(?P<target>\d+)")
def ws_member_remove(ctx, slug, target):
    c = ctx.c
    ws = get_ws(c, slug)
    caller_role = require_ws_member(c, ws, ctx.uid)
    target = int(target)
    trole = ws_role(c, ws["id"], target)
    if target != ctx.uid:
        if caller_role not in ("owner", "admin"):
            fail(403, "admin or owner required")
        if trole == "admin" and caller_role != "owner":
            fail(403, "admins cannot remove other admins")
    if trole == "owner" or target == ws["owner_id"]:
        fail(403, "the owner cannot be removed")
    if trole is None:
        return ok({"deleted": True})

    def work(c, frames):
        c.execute("DELETE FROM workspace_members WHERE workspace_id=? AND user_id=?", (ws["id"], target))
        for r in c.execute("SELECT cm.channel_id FROM channel_members cm JOIN channels ch ON ch.id=cm.channel_id "
                           "WHERE cm.user_id=? AND ch.workspace_id=? AND ch.is_dm=0",
                           (target, ws["id"])).fetchall():
            c.execute("DELETE FROM channel_members WHERE channel_id=? AND user_id=?", (r[0], target))
            emit(c, frames, r[0], "member.left", {"user_id": target, "user": user_by_id(c, target)})
    tx(work)
    return ok({"deleted": True})


@route("POST", r"/api/workspaces/(?P<slug>[^/]+)/transfer_ownership")
def ws_transfer(ctx, slug):
    c = ctx.c
    ws = get_ws(c, slug)
    role = require_ws_member(c, ws, ctx.uid)
    if role != "owner" or ws["owner_id"] != ctx.uid:
        fail(403, "only the owner can transfer ownership")
    data = ctx.body()
    if "new_owner_id" not in data:
        fail(400, "new_owner_id is required")
    new_owner = _int(data.get("new_owner_id"), "new_owner_id")
    if new_owner == ctx.uid:
        fail(400, "already the owner")

    def work(c, frames):
        trole = ws_role(c, ws["id"], new_owner)
        if trole != "admin":
            fail(400, "new owner must be an admin of the workspace")
        c.execute("UPDATE workspace_members SET role='owner' WHERE workspace_id=? AND user_id=?",
                  (ws["id"], new_owner))
        c.execute("UPDATE workspace_members SET role='admin' WHERE workspace_id=? AND user_id=?",
                  (ws["id"], ctx.uid))
        c.execute("UPDATE workspaces SET owner_id=? WHERE id=?", (new_owner, ws["id"]))
    tx(work)
    ws2 = c.execute("SELECT * FROM workspaces WHERE id=?", (ws["id"],)).fetchone()
    members = [member_obj(c, r) for r in c.execute(
        "SELECT * FROM workspace_members WHERE workspace_id=? AND user_id IN (?,?)",
        (ws["id"], ctx.uid, new_owner))]
    return ok({"workspace": ws_obj(ws2, "admin"), "members": members})


