def _invite_active(row):
    if row is None or row["revoked"]:
        return False
    if row["uses"] >= row["max_uses"]:
        return False
    if row["expires_at"] is not None and row["expires_at"] <= time.time():
        return False
    return True


@route("POST", r"/api/workspaces/(?P<slug>[^/]+)/invitations")
def inv_create(ctx, slug):
    c = ctx.c
    ws = get_ws(c, slug)
    require_ws_admin(c, ws, ctx.uid)
    data = ctx.body()
    expires_at = None
    if data.get("expires_in_seconds") is not None:
        secs = _int(data["expires_in_seconds"], "expires_in_seconds")
        if secs <= 0:
            fail(400, "expires_in_seconds must be positive")
        expires_at = time.time() + secs
    max_uses = 1
    if data.get("max_uses") is not None:
        max_uses = _int(data["max_uses"], "max_uses")
        if max_uses < 1:
            fail(400, "max_uses must be >= 1")
    invited = None
    if data.get("invited_user_id") is not None:
        invited = _int(data["invited_user_id"], "invited_user_id")
        if get_user_row(c, invited) is None:
            fail(404, "invited user not found")
    elif data.get("invited_username") is not None:
        un = data["invited_username"]
        if not isinstance(un, str):
            fail(400, "invited_username must be a string")
        r = c.execute("SELECT id FROM users WHERE username=?", (un.lstrip("@"),)).fetchone()
        if r is None:
            fail(404, "invited user not found")
        invited = r[0]
    if invited is not None:
        max_uses = 1
    role = data.get("role") or "member"
    if role not in ("member", "guest", "admin"):
        fail(400, "invalid role")
    code = secrets.token_urlsafe(12)
    iid = c.execute(
        "INSERT INTO invitations(code,workspace_id,created_by,invited_user_id,role,max_uses,uses,expires_at,"
        "revoked,created_at) VALUES(?,?,?,?,?,?,0,?,0,?)",
        (code, ws["id"], ctx.uid, invited, role, max_uses, expires_at, now_iso())).lastrowid
    row = c.execute("SELECT * FROM invitations WHERE id=?", (iid,)).fetchone()
    return ok({"invitation": invitation_obj(c, row)}, 201)


@route("GET", r"/api/workspaces/(?P<slug>[^/]+)/invitations")
