@route("POST", r"/api/invitations/(?P<code>[^/]+)/accept")
def inv_accept(ctx, code):
    uid = ctx.uid

    def work(c, frames):
        row = c.execute("SELECT * FROM invitations WHERE code=?", (code,)).fetchone()
        if not _invite_active(row):
            fail(404, "invitation not found")
        if row["invited_user_id"] is not None and row["invited_user_id"] != uid:
            fail(403, "this invitation is for a different user")
        if ws_role(c, row["workspace_id"], uid) is None:
            c.execute("UPDATE invitations SET uses=uses+1 WHERE id=?", (row["id"],))
            add_ws_member(c, frames, row["workspace_id"], uid, row["role"] or "member")
        elif row["invited_user_id"] is not None:
            c.execute("UPDATE invitations SET uses=uses+1 WHERE id=?", (row["id"],))
        return row["id"], row["workspace_id"]
    iid, wid = tx(work)
    c = ctx.c
    ws = c.execute("SELECT * FROM workspaces WHERE id=?", (wid,)).fetchone()
    inv = c.execute("SELECT * FROM invitations WHERE id=?", (iid,)).fetchone()
    mem = c.execute("SELECT * FROM workspace_members WHERE workspace_id=? AND user_id=?", (wid, uid)).fetchone()
    return ok({"workspace": ws_obj(ws, mem["role"]), "invitation": invitation_obj(c, inv),
               "member": member_obj(c, mem)})


