@route("POST", r"/api/workspaces/(?P<slug>[^/]+)/channels")
def ch_create(ctx, slug):
    c = ctx.c
    ws = get_ws(c, slug)
    role = require_ws_member(c, ws, ctx.uid)
    data = ctx.body()
    name = data.get("name")
    if not isinstance(name, str) or not CHANNEL_RE.match(name):
        fail(400, "name must be lowercase kebab-case, at most 32 chars")
    is_private = data.get("is_private", False)
    if is_private is None:
        is_private = False
    if not isinstance(is_private, (bool, int)):
        fail(400, "is_private must be a boolean")
    is_private = bool(is_private)
    topic = data.get("topic", "")
    if topic is None:
        topic = ""
    if not isinstance(topic, str) or len(topic) > 250:
        fail(400, "topic must be a string up to 250 chars")
    if role == "guest":
        fail(403, "guests cannot create channels")
    if is_private and role not in ("owner", "admin"):
        fail(403, "only admins can create private channels")
    uid = ctx.uid

    def work(c, frames):
        if c.execute("SELECT 1 FROM channels WHERE workspace_id=? AND name=? AND is_dm=0",
                     (ws["id"], name)).fetchone():
            fail(409, "a channel with this name already exists")
        now = now_iso()
        cid = c.execute("INSERT INTO channels(workspace_id,name,is_private,is_dm,topic,created_by,created_at) "
                        "VALUES(?,?,?,0,?,?,?)", (ws["id"], name, int(is_private), topic, uid, now)).lastrowid
        c.execute("INSERT INTO channel_members(channel_id,user_id,joined_at) VALUES(?,?,?)", (cid, uid, now))
        return cid
    cid = tx(work)
    return ok({"channel": channel_obj(c, get_channel(c, cid), uid)}, 201)


@route("GET", r"/api/channels/(?P<cid>\d+)")
def ch_get(ctx, cid):
