    if ch["is_dm"]:
        d = _dm_obj(c, ch, ctx.uid)
    return ok({"channel": d})


def _join(ctx, ch):
    """Join logic shared by POST /join."""
    uid = ctx.uid
    c = ctx.c
    if is_channel_member(c, ch["id"], uid):
        return
    if ch["is_dm"] or ch["is_private"]:
        fail(403, "private channel requires an invitation")
    ws = c.execute("SELECT * FROM workspaces WHERE id=?", (ch["workspace_id"],)).fetchone()
    role = ws_role(c, ch["workspace_id"], uid)
    if role is None:
        if ws is None or ws["join_mode"] != "open":
            fail(403, "workspace is invite-only")
    elif role == "guest":
        fail(403, "guests cannot join public channels")
    require_not_archived(ch)

    def work(c, frames):
        if ws_role(c, ch["workspace_id"], uid) is None:
            add_ws_member(c, frames, ch["workspace_id"], uid, "member", join_general=False)
            gid = general_channel_id(c, ch["workspace_id"])
            if gid is not None and gid != ch["id"]:
                g = c.execute("SELECT is_archived FROM channels WHERE id=?", (gid,)).fetchone()
                if g and not g[0]:
                    add_channel_member(c, frames, gid, uid)
        add_channel_member(c, frames, ch["id"], uid)
    tx(work)


@route("POST", r"/api/channels/(?P<cid>\d+)/join")
def ch_join(ctx, cid):
    c = ctx.c
    ch = get_channel(c, cid)
    _join(ctx, ch)
    return ok({"channel": channel_obj(c, get_channel(c, cid), ctx.uid)})


@route("POST", r"/api/channels/(?P<cid>\d+)/leave")
def ch_leave(ctx, cid):
    c = ctx.c
    ch = get_channel(c, cid)
    uid = ctx.uid

    def work(c, frames):
        cur = c.execute("DELETE FROM channel_members WHERE channel_id=? AND user_id=?", (ch["id"], uid))
        if cur.rowcount:
            emit(c, frames, ch["id"], "member.left", {"user_id": uid, "user": user_by_id(c, uid)})
    if is_channel_member(c, ch["id"], uid):
        tx(work)
    return ok({"channel": channel_obj(c, get_channel(c, cid), uid)})


@route("GET", r"/api/channels/(?P<cid>\d+)/members")
def ch_members(ctx, cid):
    c = ctx.c
    ch = get_channel(c, cid)
    require_channel_access(c, ch, ctx.uid)
    rows = c.execute("SELECT u.* FROM channel_members cm JOIN users u ON u.id=cm.user_id "
                     "WHERE cm.channel_id=? ORDER BY cm.joined_at, u.id", (ch["id"],)).fetchall()
    return ok({"members": [user_obj(r) for r in rows]})


def _resolve_user_ref(c, data):
    if data.get("user_id") is not None:
        uid = _int(data["user_id"], "user_id")
        if get_user_row(c, uid) is None:
            fail(404, "user not found")
        return uid
    un = data.get("username")
    if isinstance(un, str) and un.strip():
        r = c.execute("SELECT id FROM users WHERE username=?", (un.strip().lstrip("@"),)).fetchone()
        if r is None:
            fail(404, "user not found")
        return r[0]
    fail(400, "user_id or username is required")


def _invite_to_channel(ctx, ch, target):
    """Add target to channel (caller already has access). Returns target user obj."""
    c = ctx.c
    if ch["is_dm"]:
        fail(400, "cannot add members to a DM")
    require_not_archived(ch)
    ws = c.execute("SELECT * FROM workspaces WHERE id=?", (ch["workspace_id"],)).fetchone()
    trole = ws_role(c, ch["workspace_id"], target)
    if trole is None and (ws is None or ws["join_mode"] != "open"):
        fail(403, "user is not a member of this workspace")

    def work(c, frames):
        if ws_role(c, ch["workspace_id"], target) is None:
            add_ws_member(c, frames, ch["workspace_id"], target, "member", join_general=False)
        add_channel_member(c, frames, ch["id"], target)
    tx(work)
    return user_by_id(c, target)


