        if cur[0] != topic:
            c.execute("UPDATE channels SET topic=? WHERE id=?", (topic, ch["id"]))
            emit(c, frames, ch["id"], "channel.updated", {"channel": channel_obj(c, get_channel(c, ch["id"]))})
    tx(work)


@route("PATCH", r"/api/channels/(?P<cid>\d+)")
def ch_patch(ctx, cid):
    c = ctx.c
    ch = get_channel(c, cid)
    _check_channel_editor(c, ch, ctx.uid)
    require_not_archived(ch)
    data = ctx.body()
    updates = {}
    if "topic" in data:
        t = data["topic"]
        if t is None:
            t = ""
        if not isinstance(t, str) or len(t) > 250:
            fail(400, "topic must be a string up to 250 chars")
        updates["topic"] = t
    if "name" in data and not ch["is_dm"]:
        n = data["name"]
        if not isinstance(n, str) or not CHANNEL_RE.match(n):
            fail(400, "name must be lowercase kebab-case, at most 32 chars")
        if n != ch["name"]:
            updates["name"] = n

    def work(c, frames):
        if "name" in updates and c.execute(
                "SELECT 1 FROM channels WHERE workspace_id=? AND name=? AND is_dm=0 AND id<>?",
                (ch["workspace_id"], updates["name"], ch["id"])).fetchone():
            fail(409, "a channel with this name already exists")
        cur = get_channel(c, ch["id"])
        changed = {k: v for k, v in updates.items() if cur[k] != v}
        if changed:
            sets = ", ".join("%s=?" % k for k in changed)
            c.execute("UPDATE channels SET %s WHERE id=?" % sets, (*changed.values(), ch["id"]))
            emit(c, frames, ch["id"], "channel.updated", {"channel": channel_obj(c, get_channel(c, ch["id"]))})
    if updates:
        tx(work)
    return ok({"channel": channel_obj(c, get_channel(c, cid), ctx.uid)})


