# ---------------------------------------------------------------------------------------------
# mentions

def compute_mentions(c, ch, author_id, body, online=None):
    tokens = []
    for m in MENTION_RE.finditer(body):
        end = m.end()
        nxt = body[end:end + 2]
        if nxt[:1] == "@" or (nxt[:1] == "." and len(nxt) > 1 and (nxt[1].isalnum() or nxt[1] == "_")):
            continue  # email/domain-shaped
        tokens.append(m.group(1))
    if not tokens:
        return []
    out = []
    seen = set()

    def add(uid):
        if uid != author_id and uid not in seen:
            seen.add(uid)
            out.append(uid)

    members = None

    def channel_members():
        nonlocal members
        if members is None:
            members = [r[0] for r in c.execute(
                "SELECT user_id FROM channel_members WHERE channel_id=? ORDER BY joined_at, user_id",
                (ch["id"],))]
        return members

    ws_id = ch["workspace_id"]
    for tok in tokens:
        low = tok.lower()
        if low in SPECIAL_ALL:
            for u in channel_members():
                add(u)
            continue
        if low == "here":
            on = online if online is not None else set()
            for u in channel_members():
                if u in on:
                    add(u)
            continue
        candidates = [tok]
        if tok.rstrip("-_") != tok and tok.rstrip("-_"):
            candidates.append(tok.rstrip("-_"))
        matched = False
        for cand in candidates:
            r = c.execute("SELECT id FROM users WHERE username=?", (cand,)).fetchone()
            if r is not None:
                uid = r[0]
                if ws_id is not None:
                    allowed = ws_role(c, ws_id, uid) is not None
                else:
                    allowed = uid in channel_members()
                if allowed:
                    add(uid)
                matched = True
                break
        if ws_id is not None:
            for cand in candidates:
                g = c.execute("SELECT id FROM user_groups WHERE workspace_id=? AND handle=?",
                              (ws_id, cand)).fetchone()
                if g is not None:
                    cm = set(channel_members())
                    for r in c.execute("SELECT user_id FROM user_group_members WHERE group_id=? ORDER BY user_id",
                                       (g[0],)):
                        if r[0] in cm:
                            add(r[0])
                    break
        del matched
    return out


def _needs_online(body):
    return re.search(r"(?<![\w.+\-@/])@here\b", body, re.I) is not None


