def _create_message(ctx, ch, body, parent_id=None, file_ids=(), blocks=None):
    uid = ctx.uid
    online = events.online_user_ids() if _needs_online(body) else None
    blocks_json = json.dumps(blocks) if blocks is not None else None

    def work(c, frames):
        for fid in file_ids:
            f = c.execute("SELECT uploader_id, message_id FROM files WHERE id=?", (fid,)).fetchone()
            if f is None or f[0] != uid or f[1] is not None:
                fail(400, "file %s is not attachable" % fid)
        mentions = compute_mentions(c, ch, uid, body, online)
        seq_guess = events.head_seq(c, ch["id"]) + 1
        now = now_iso()
        mid = c.execute(
            "INSERT INTO messages(channel_id,author_id,body,parent_id,blocks,seq,created_at) VALUES(?,?,?,?,?,?,?)",
            (ch["id"], uid, body, parent_id, blocks_json, seq_guess, now)).lastrowid
        for fid in file_ids:
            c.execute("UPDATE files SET message_id=? WHERE id=?", (mid, fid))
        for m in mentions:
            c.execute("INSERT OR IGNORE INTO message_mentions(message_id,user_id) VALUES(?,?)", (mid, m))
        msg = message_obj(c, c.execute("SELECT * FROM messages WHERE id=?", (mid,)).fetchone())
        if parent_id is None:
            frame = emit(c, frames, ch["id"], "message.new", {"message": msg})
        else:
            frame = emit(c, frames, ch["id"], "message.reply",
                         {"message": msg, "parent_id": parent_id, "reply_count": reply_count(c, parent_id)})
        if frame["seq"] != seq_guess:
            c.execute("UPDATE messages SET seq=? WHERE id=?", (frame["seq"], mid))
            msg["seq"] = frame["seq"]
        return msg
    return tx(work)


def _validate_body(body, allow_empty=False):
    if body is None:
        body = ""
    if not isinstance(body, str):
        fail(400, "body must be a string")
    if not body.strip() and not allow_empty:
        fail(400, "body cannot be empty")
    if len(body) > MAX_BODY:
        fail(400, "body too long")
    return body


@route("POST", r"/api/channels/(?P<cid>\d+)/messages")
def msg_create(ctx, cid):
    c = ctx.c
    ch = get_channel(c, cid)
    require_channel_access(c, ch, ctx.uid)
    data = ctx.body()
    raw = data.get("body", "")
    if raw is None:
        raw = ""
    if not isinstance(raw, str):
        fail(400, "body must be a string")
    stripped = raw.strip()
    if stripped.startswith("/") and not stripped.startswith("//"):
        return _slash(ctx, ch, raw, stripped, data)
    require_not_archived(ch)
    file_ids = data.get("file_ids") or []
    if not isinstance(file_ids, list):
        fail(400, "file_ids must be a list")
    file_ids = [_int(f, "file_ids") for f in file_ids]
    if len(set(file_ids)) != len(file_ids):
        fail(400, "duplicate file ids")
    body = _validate_body(raw, allow_empty=bool(file_ids))
    blocks = data.get("blocks")
    parent_id = _resolve_parent(c, ch, data.get("parent_id"))
    msg = _create_message(ctx, ch, body, parent_id, file_ids, blocks)
    return ok({"message": msg}, 201)


def _resolve_parent(c, ch, pid):
    if pid is None:
        return None
    pid = _int(pid, "parent_id")
    p = c.execute("SELECT * FROM messages WHERE id=?", (pid,)).fetchone()
    if p is None or p["channel_id"] != ch["id"] or p["deleted_at"] is not None:
        fail(400, "parent message not found in this channel")
    if p["parent_id"] is not None:
        return p["parent_id"]
    return pid


def _slash(ctx, ch, raw, stripped, data):
    c = ctx.c
    parts = stripped.split(None, 1)
    cmd = parts[0].lower()
    rest = parts[1].strip() if len(parts) > 1 else ""
    if cmd == "/unarchive":
        ch_obj = _set_archived(ctx, ch, False)
        return ok({"message": None, "channel": ch_obj}, 201)
    if cmd not in ("/me", "/shrug", "/topic", "/invite", "/archive"):
        fail(400, "unknown command %s" % cmd)
    require_not_archived(ch)
    if cmd == "/me":
        if not rest:
            fail(400, "/me requires text")
        body = _validate_body(raw)
        parent_id = _resolve_parent(c, ch, data.get("parent_id"))
        return ok({"message": _create_message(ctx, ch, body, parent_id)}, 201)
    if cmd == "/shrug":
        body = (rest + " " + SHRUG) if rest else SHRUG
        body = _validate_body(body)
        parent_id = _resolve_parent(c, ch, data.get("parent_id"))
        return ok({"message": _create_message(ctx, ch, body, parent_id)}, 201)
    if cmd == "/topic":
        if len(rest) > 250:
            fail(400, "topic must be at most 250 chars")
        _check_channel_editor(c, ch, ctx.uid)
        _set_topic(ctx, ch, rest)
        return ok({"message": None, "channel": channel_obj(c, get_channel(c, ch["id"]), ctx.uid)}, 201)
    if cmd == "/invite":
        m = re.match(r"^@?([A-Za-z0-9_]+)$", rest.split()[0]) if rest else None
        if not m:
            fail(400, "usage: /invite @user")
        r = c.execute("SELECT id FROM users WHERE username=?", (m.group(1),)).fetchone()
        if r is None:
            fail(404, "user not found")
        if ch["is_private"] and not is_channel_member(c, ch["id"], ctx.uid):
            fail(403, "not a member of this channel")
        u = _invite_to_channel(ctx, ch, r[0])
        return ok({"message": None, "invited_user": u,
                   "channel": channel_obj(c, get_channel(c, ch["id"]), ctx.uid)}, 201)
    if cmd == "/archive":
        ch_obj = _set_archived(ctx, ch, True)
        return ok({"message": None, "channel": ch_obj}, 201)
    fail(400, "unknown command")


@route("GET", r"/api/channels/(?P<cid>\d+)/messages")
def msg_list(ctx, cid):
    c = ctx.c
    ch = get_channel(c, cid)
    require_channel_access(c, ch, ctx.uid)
    limit = _limit(ctx)
    q = ctx.req.query
    sql = "SELECT * FROM messages WHERE channel_id=? AND deleted_at IS NULL"
    args = [ch["id"]]
    if not _truthy(q.get("include_replies")):
        sql += " AND parent_id IS NULL"
    if q.get("before"):
        sql += " AND id<?"
        args.append(_int(q["before"], "before"))
    if q.get("after"):
        sql += " AND id>?"
        args.append(_int(q["after"], "after"))
    sql += " ORDER BY id DESC LIMIT ?"
    args.append(limit)
    cache = {}
    rows = c.execute(sql, args).fetchall()
    return ok({"messages": [message_obj(c, r, cache) for r in rows]})


