@route("PATCH", r"/api/messages/(?P<mid>\d+)")
def msg_patch(ctx, mid):
    c = ctx.c
    m = get_message(c, mid, allow_deleted=True)
    ch = get_channel(c, m["channel_id"])
    if m["author_id"] != ctx.uid:
        if m["deleted_at"] is not None and not can_read_channel(c, ch, ctx.uid):
            fail(404, "message not found")
        fail(403, "only the author can edit a message")
    if m["deleted_at"] is not None:
        fail(409, "message has been deleted")
    require_not_archived(ch)
    data = ctx.body()
    body = _validate_body(data.get("body"))
    online = events.online_user_ids() if _needs_online(body) else None
    uid = ctx.uid

    def work(c, frames):
        cur = c.execute("SELECT * FROM messages WHERE id=?", (m["id"],)).fetchone()
        if cur["deleted_at"] is not None:
            fail(409, "message has been deleted")
        mentions = compute_mentions(c, ch, uid, body, online)
        c.execute("UPDATE messages SET body=?, edited_at=? WHERE id=?", (body, now_iso(), m["id"]))
        c.execute("DELETE FROM message_mentions WHERE message_id=?", (m["id"],))
        for u in mentions:
            c.execute("INSERT OR IGNORE INTO message_mentions(message_id,user_id) VALUES(?,?)", (m["id"], u))
        msg = message_obj(c, c.execute("SELECT * FROM messages WHERE id=?", (m["id"],)).fetchone())
        emit(c, frames, ch["id"], "message.updated", {"message": msg})
        return msg
    return ok({"message": tx(work)})


@route("DELETE", r"/api/messages/(?P<mid>\d+)")
def msg_delete(ctx, mid):
    c = ctx.c
    m = get_message(c, mid, allow_deleted=True)
    ch = get_channel(c, m["channel_id"])
    if m["author_id"] != ctx.uid and not is_ws_owner(c, ch["workspace_id"], ctx.uid):
        fail(403, "only the author or workspace owner can delete")
    if m["deleted_at"] is not None:
        return ok({"deleted": True})
    require_not_archived(ch)

    def work(c, frames):
        cur = c.execute("SELECT deleted_at, parent_id FROM messages WHERE id=?", (m["id"],)).fetchone()
        if cur[0] is not None:
            return
        c.execute("UPDATE messages SET deleted_at=? WHERE id=?", (now_iso(), m["id"]))
        data = {"message_id": m["id"], "parent_id": cur[1]}
        if cur[1] is not None:
            data["reply_count"] = reply_count(c, cur[1])
        emit(c, frames, ch["id"], "message.deleted", data)
    tx(work)
    return ok({"deleted": True})


