    if data.get("user_id") is None:
        fail(400, "user_id is required")
    other = _int(data["user_id"], "user_id")
    if get_user_row(c, other) is None:
        fail(404, "user not found")
    me_id = ctx.uid
    a, b = sorted((me_id, other))
    key = "%d:%d" % (a, b)

    def work(c, frames):
        r = c.execute("SELECT id FROM channels WHERE dm_key=?", (key,)).fetchone()
        if r:
            return r[0]
        shared = c.execute(
            "SELECT a.workspace_id FROM workspace_members a JOIN workspace_members b "
            "ON a.workspace_id=b.workspace_id WHERE a.user_id=? AND b.user_id=? ORDER BY a.workspace_id LIMIT 1",
            (me_id, other)).fetchone()
        if shared is None:
            shared = c.execute("SELECT workspace_id FROM workspace_members WHERE user_id=? ORDER BY workspace_id "
                               "LIMIT 1", (me_id,)).fetchone()
        ws_id = shared[0] if shared else None
        now = now_iso()
        cid = c.execute("INSERT INTO channels(workspace_id,name,is_private,is_dm,topic,created_by,created_at,dm_key) "
                        "VALUES(?,?,1,1,'',?,?,?)", (ws_id, "dm-%d-%d" % (a, b), me_id, now, key)).lastrowid
        for u in {a, b}:
            c.execute("INSERT OR IGNORE INTO channel_members(channel_id,user_id,joined_at) VALUES(?,?,?)",
                      (cid, u, now))
        return cid
    cid = tx(work)
    return ok({"channel_id": cid, "channel": _dm_obj(c, get_channel(c, cid), me_id)})


@route("GET", r"/api/dms")
def dm_list(ctx):
