def _parse_multipart(body, ctype):
    m = re.search(r'boundary=(?:"([^"]+)"|([^;\s]+))', ctype or "", re.I)
    if not m:
        fail(400, "multipart boundary missing")
    boundary = (m.group(1) or m.group(2)).encode("latin-1")
    delim = b"--" + boundary
    parts = []
    pos = body.find(delim)
    if pos < 0:
        fail(400, "malformed multipart body")
    while True:
        start = pos + len(delim)
        if body[start:start + 2] == b"--":
            break
        nxt = body.find(delim, start)
        if nxt < 0:
            chunk = body[start:]
        else:
            chunk = body[start:nxt]
        if chunk.startswith(b"\r\n"):
            chunk = chunk[2:]
        elif chunk.startswith(b"\n"):
            chunk = chunk[1:]
        he = chunk.find(b"\r\n\r\n")
        sep = 4
        if he < 0:
            he = chunk.find(b"\n\n")
            sep = 2
        if he >= 0:
            raw_headers = chunk[:he].decode("utf-8", "replace")
            content = chunk[he + sep:]
            if content.endswith(b"\r\n"):
                content = content[:-2]
            elif content.endswith(b"\n"):
                content = content[:-1]
            headers = {}
            for line in raw_headers.splitlines():
                k, _, v = line.partition(":")
                headers[k.strip().lower()] = v.strip()
            params = {}
            for pm in re.finditer(r';\s*([A-Za-z0-9_*.-]+)\s*=\s*("(?:[^"\\]|\\.)*"|[^;]*)',
                                  headers.get("content-disposition", "")):
                v = pm.group(2).strip()
                if v.startswith('"') and v.endswith('"'):
                    v = v[1:-1].replace('\\"', '"').replace("\\\\", "\\")
                params[pm.group(1).lower()] = v
            fname = params.get("filename")
            if "filename*" in params:
                v = params["filename*"]
                if "''" in v:
                    enc, _, val = v.partition("''")
                    try:
                        fname = urllib.parse.unquote(val, encoding=enc or "utf-8")
                    except Exception:
                        fname = urllib.parse.unquote(val)
            parts.append({"name": params.get("name"), "filename": fname,
                          "content_type": headers.get("content-type"), "data": content})
        if nxt < 0:
            break
        pos = nxt
    return parts


@route("POST", r"/api/files")
def file_upload(ctx):
    req = ctx.req
    if len(req.body) > config.MAX_UPLOAD + 256 * 1024:
        fail(413, "file too large")
    ctype = req.headers.get("content-type", "")
    if "multipart/form-data" not in ctype.lower():
        fail(400, "multipart/form-data required")
    parts = _parse_multipart(req.body, ctype)
    part = None
    for p in parts:
        if p["name"] == "file":
            part = p
            break
    if part is None:
        for p in parts:
            if p["filename"] is not None:
                part = p
                break
    if part is None:
        fail(400, "file part is required")
    data = part["data"]
    if len(data) > config.MAX_UPLOAD:
        fail(413, "file too large")
    fname = (part["filename"] or "file").replace("\\", "/").split("/")[-1].strip() or "file"
    fname = "".join(ch for ch in fname if ch >= " " and ch != "\x7f")[:255] or "file"
    ct = part["content_type"] or mimetypes.guess_type(fname)[0] or "application/octet-stream"
    storage = secrets.token_hex(16)
    os.makedirs(config.FILES_DIR, exist_ok=True)
    path = os.path.join(config.FILES_DIR, storage)
    with open(path, "wb") as f:
        f.write(data)
    try:
        fid = ctx.c.execute("INSERT INTO files(uploader_id,filename,content_type,size,storage_name,created_at) "
                            "VALUES(?,?,?,?,?,?)", (ctx.uid, fname, ct, len(data), storage, now_iso())).lastrowid
    except Exception:
        try:
            os.unlink(path)
        except OSError:
            pass
        raise
    row = ctx.c.execute("SELECT * FROM files WHERE id=?", (fid,)).fetchone()
    return ok({"file": file_obj(row)}, 201)


@route("GET", r"/api/files")
def file_list(ctx):
    rows = ctx.c.execute("SELECT * FROM files WHERE uploader_id=? ORDER BY id DESC LIMIT 200",
                         (ctx.uid,)).fetchall()
    return ok({"files": [file_obj(r) for r in rows]})


def _get_file(ctx, fid):
    c = ctx.c
    row = c.execute("SELECT * FROM files WHERE id=?", (int(fid),)).fetchone()
    if row is None:
        fail(404, "file not found")
    if row["uploader_id"] != ctx.uid:
        if row["message_id"] is None:
            fail(403, "no access to this file")
        m = c.execute("SELECT channel_id FROM messages WHERE id=?", (row["message_id"],)).fetchone()
        if m is None:
            fail(403, "no access to this file")
        ch = c.execute("SELECT * FROM channels WHERE id=?", (m[0],)).fetchone()
        if ch is None or not can_read_channel(c, ch, ctx.uid):
            fail(403, "no access to this file")
    return row


@route("GET", r"/api/files/(?P<fid>\d+)")
def file_get(ctx, fid):
    return ok({"file": file_obj(_get_file(ctx, fid))})


@route("GET", r"/api/files/(?P<fid>\d+)/download")
def file_download(ctx, fid):
    row = _get_file(ctx, fid)
    path = os.path.join(config.FILES_DIR, row["storage_name"])
    try:
        with open(path, "rb") as f:
            data = f.read()
    except OSError:
        fail(404, "file content missing")
    fname = row["filename"]
    ascii_name = "".join(ch if 32 <= ord(ch) < 127 and ch not in '"\\' else "_" for ch in fname)
    disp = 'attachment; filename="%s"' % ascii_name
    if ascii_name != fname:
        disp += "; filename*=UTF-8''%s" % urllib.parse.quote(fname, safe="")
    return Response(200, data, headers={"Content-Disposition": disp}, content_type=row["content_type"])


