# search

def _like_escape(s):
    return s.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_")


@route("GET", r"/api/search")
def search(ctx):
    c = ctx.c
    q = (ctx.req.query.get("q") or "").strip()
    limit = _limit(ctx, 50, 200)
    if not q:
        return ok({"results": [], "messages": []})
    sql = ("SELECT m.* FROM messages m JOIN channels ch ON ch.id=m.channel_id "
           "WHERE m.deleted_at IS NULL AND m.body LIKE ? ESCAPE '\\' AND ("
           " EXISTS(SELECT 1 FROM channel_members cm WHERE cm.channel_id=ch.id AND cm.user_id=?)"
           " OR (ch.is_private=0 AND ch.is_dm=0 AND EXISTS(SELECT 1 FROM workspace_members wm "
           "     WHERE wm.workspace_id=ch.workspace_id AND wm.user_id=? AND wm.role<>'guest')))")
    args = ["%" + _like_escape(q) + "%", ctx.uid, ctx.uid]
    wsid = ctx.req.query.get("workspace_id")
    if wsid:
        sql += " AND ch.workspace_id=?"
        args.append(_int(wsid, "workspace_id"))
    if ctx.req.query.get("channel_id"):
        sql += " AND ch.id=?"
        args.append(_int(ctx.req.query["channel_id"], "channel_id"))
    sql += " ORDER BY m.id DESC LIMIT ?"
    args.append(limit)
    cache = {}
    results = []
    chcache = {}
    for r in c.execute(sql, args).fetchall():
        d = message_obj(c, r, cache)
        cid = r["channel_id"]
        if cid not in chcache:
            chrow = get_channel(c, cid)
            chcache[cid] = {"id": cid, "name": chrow["name"], "workspace_id": chrow["workspace_id"],
                            "is_dm": bool(chrow["is_dm"]), "is_private": bool(chrow["is_private"])}
        d["channel"] = chcache[cid]
        d["workspace_id"] = chcache[cid]["workspace_id"]
        results.append(d)
    return ok({"results": results})


