    show('app', name === 'app');
    var box = byId('user-box');
    if (name === 'onboarding') byId('onboarding-user-slot').appendChild(box);
    else if (name === 'app') byId('sidebar-user-slot').appendChild(box);
    if (name !== 'app') { closeAllModals(); closeEmojiPicker(); }
  }

  function showAuth(mode) {
    showView('auth');
    setAuthMode(mode || 'login');
    setTimeout(function () { var u = byId('auth-username'); if (u) u.focus(); }, 0);
  }

  function setAuthMode(mode) {
    var form = byId('auth-form');
    form.setAttribute('data-mode', mode);
    var signup = mode === 'signup';
    byId('auth-title').textContent = signup ? 'Create your Huddle account' : 'Sign in to Huddle';
    byId('auth-subtitle').textContent = signup ? 'Pick a username (letters, numbers and underscores) and a password of at least 8 characters.' : 'Welcome back! Enter your username and password.';
    byId('auth-submit').textContent = signup ? 'Create account' : 'Sign in';
    byId('auth-toggle-prompt').textContent = signup ? 'Already have an account?' : 'New to Huddle?';
    byId('auth-toggle').textContent = signup ? 'Sign in instead' : 'Create an account';
    show('auth-display-name-field', signup);
    show('auth-password-hint', signup);
