      if (!/^[A-Za-z0-9_]+$/.test(username)) return setError('auth-error', 'Usernames may only contain letters, numbers and underscores.');
      if (username.length > 64) return setError('auth-error', 'That username is too long.');
      if (password.length < 8) return setError('auth-error', 'Password must be at least 8 characters long.');
    } else if (!password) {
      return setError('auth-error', 'Please enter your password.');
    }
