    if (mode === 'signup' && displayName) body.display_name = displayName;
    authBusy = true;
    byId('auth-submit').classList.add('is-busy');
    api('POST', mode === 'signup' ? '/api/auth/register' : '/api/auth/login', body, { quiet: true, noAuthRedirect: true })
