    var before = new Set(S.workspaces.map(function (w) { return key(w.id); }));
    api('POST', '/api/invitations/' + encodeURIComponent(code) + '/accept', {}, { quiet: true }).then(function (r) {
      byId('join-workspace-form').reset();
