        S.workspaces = S.workspaces.filter(function (w) { return w.slug !== slug; });
        if (other) return openWorkspace(other.slug);
        showOnboarding(false);
      } else if (!S.ws) {
        showOnboarding(false);
      }
    });
  }

  function setChannels(list) {
    var prevById = new Map(S.channels.map(function (c) { return [key(c.id), c]; }));
    S.channels = list.filter(function (c) { return c && !c.is_dm; }).map(function (c) {
      var prev = prevById.get(key(c.id));
      var merged = Object.assign({}, prev || {}, c);
      if (c.is_member === undefined && prev && prev.is_member !== undefined) merged.is_member = prev.is_member;
      return merged;
    });
    if (S.current && !S.current.is_dm) {
      var cur = findChannel(S.current.id);
      if (cur) { S.current = cur; }
    }
  }

  function findChannel(id) {
    return S.channels.find(function (c) { return sameId(c.id, id); }) || S.dms.find(function (c) { return sameId(c.id, id); }) || null;
  }

  function loadMembers() {
    if (!S.ws) return Promise.resolve([]);
    var slug = S.ws.slug;
    return api('GET', '/api/workspaces/' + encodeURIComponent(slug) + '/members', null, { quiet: true }).then(function (d) {
      if (!S.ws || S.ws.slug !== slug) return [];
      S.members = (d.members || []).map(function (m) {
        var uid = m.user_id !== undefined ? m.user_id : (m.user ? m.user.id : m.id);
        var u = m.user || (m.username ? m : null);
        if (u) cacheUser(Object.assign({}, u, { id: uid }));
        return { user_id: uid, role: m.role || 'member', user: u ? getUser(uid) : null };
      });
      S.members.forEach(function (m) { if (!m.user) ensureUser(m.user_id).then(function (u) { m.user = u; }); });
      var mine = S.members.find(function (m) { return S.me && sameId(m.user_id, S.me.id); });
      if (mine && mine.role) S.myRole = mine.role;
      return S.members;
    }).catch(function () { return []; });
  }

  function renderWorkspaceHeader() {
    if (!S.ws) return;
    byId('workspace-name').textContent = S.ws.name || S.ws.slug;
    byId('workspace-slug').textContent = S.ws.slug ? S.ws.slug : '';
    byId('workspace-avatar').textContent = initialOf(S.ws.name || S.ws.slug);
    byId('workspace-header').setAttribute('data-workspace-slug', S.ws.slug || '');
    document.title = (S.current ? channelLabel(S.current) + ' — ' : '') + (S.ws.name || 'Huddle') + ' — Huddle';
  }

  function toggleWorkspaceMenu(force) {
    var menu = byId('workspace-menu');
    var open = force !== undefined ? force : menu.hidden;
    if (!open) { menu.hidden = true; byId('workspace-switcher-btn').setAttribute('aria-expanded', 'false'); return; }
    clear(menu);
    menu.appendChild(el('div', { class: 'menu-label' }, 'Workspaces'));
    S.workspaces.forEach(function (w) {
      menu.appendChild(el('button', {
        type: 'button', class: 'menu-item', role: 'menuitem', 'data-testid': 'workspace-menu-item', 'data-workspace-slug': w.slug,
        onclick: function () { toggleWorkspaceMenu(false); if (!S.ws || S.ws.slug !== w.slug) openWorkspace(w.slug); }
      }, [w.name || w.slug, S.ws && S.ws.slug === w.slug ? el('span', { class: 'check' }, '✓') : null]));
    });
    menu.appendChild(el('div', { class: 'menu-sep' }));
    menu.appendChild(el('button', {
      type: 'button', class: 'menu-item', role: 'menuitem', 'data-testid': 'add-workspace-btn',
      onclick: function () { toggleWorkspaceMenu(false); showOnboarding(true); }
    }, '+ Create or join a workspace'));
    menu.appendChild(el('button', {
      type: 'button', class: 'menu-item', role: 'menuitem',
      onclick: function () { toggleWorkspaceMenu(false); openWorkspaceSettings(); }
    }, 'Workspace settings'));
    menu.hidden = false;
    byId('workspace-switcher-btn').setAttribute('aria-expanded', 'true');
  }

  function periodicRefresh() {
    if (!S.ws || !S.token || document.hidden) return;
    var slug = S.ws.slug;
    api('GET', '/api/workspaces/' + encodeURIComponent(slug) + '?include_archived=1', null, { quiet: true }).then(function (d) {
      if (!S.ws || S.ws.slug !== slug) return;
      S.ws = d.workspace || S.ws;
      if (d.my_role) S.myRole = d.my_role;
      setChannels(d.channels || []);
      S.channels.forEach(function (c) { if (c.is_member !== false && !c.is_archived) subscribe(c.id); });
      renderWorkspaceHeader();
      renderChannelList();
      if (S.current && !S.current.is_dm) { renderHeader(); renderComposerState(); }
      if (Array.isArray(d.dms)) setDms(d.dms);
    }).catch(function () { /* ignore */ });
    loadDms(false);
    loadWorkspaces().catch(function () { /* ignore */ });
  }

  // ------------------------------------------------------------------ channel list
  function channelLabel(ch) {
    if (!ch) return '';
    if (ch.is_dm) return dmName(ch);
    return '#' + ch.name;
  }

  function renderChannelList() {
    var ul = byId('channel-list');
    clear(ul);
    var list = S.channels.slice().sort(function (a, b) {
      if (!!a.is_archived !== !!b.is_archived) return a.is_archived ? 1 : -1;
      return String(a.name).localeCompare(String(b.name));
    });
    if (!list.length) ul.appendChild(el('li', { class: 'sidebar-empty' }, 'No channels yet'));
    list.forEach(function (c) {
      var k = key(c.id);
      var active = S.current && !S.current.is_dm && sameId(S.current.id, c.id);
      var unread = !active && S.unread[k] > 0 ? S.unread[k] : 0;
      var cls = 'channel-entry' + (active ? ' active' : '') + (unread ? ' unread' : '') +
        (c.is_member === false ? ' not-member' : '') + (c.is_archived ? ' archived' : '');
      var btn = el('button', {
        type: 'button', class: cls, 'data-testid': 'channel-entry', 'data-channel-id': c.id, 'data-channel-name': c.name,
        'aria-current': active ? 'page' : null, title: (c.is_private ? 'Private channel ' : 'Channel ') + c.name +
          (c.is_archived ? ' (archived)' : '') + (c.is_member === false ? ' — click to join' : ''),
        onclick: function () { selectChannel(c); }
      }, [
        el('span', { class: 'channel-hash', 'aria-hidden': 'true' }, c.is_private ? '🔒' : '#'),
        el('span', { class: 'channel-entry-name' }, (c.is_private ? '' : ' ') + c.name),
        unread ? el('span', { class: 'unread-badge', 'data-testid': 'unread-badge' }, String(unread)) : null
      ]);
      ul.appendChild(el('li', null, btn));
    });
  }

  // ------------------------------------------------------------------ DMs
  function normalizeDm(d) {
    if (!d) return null;
    var ch = d.channel && typeof d.channel === 'object' ? d.channel : d;
    var id = d.channel_id !== undefined ? d.channel_id : ch.id;
    if (id === undefined || id === null) return null;
    var me = S.me ? S.me.id : null;
    var other = d.other_user || d.user || d.peer || ch.other_user || null;
    var pick = function (arr) {
      if (!Array.isArray(arr)) return null;
      var found = null;
      arr.forEach(function (m) {
        if (found) return;
        var u = m && typeof m === 'object' ? (m.user || m) : (getUser(m) || { id: m });
        var uid = u.id !== undefined ? u.id : u.user_id;
        if (!sameId(uid, me)) found = Object.assign({}, u, { id: uid });
      });
      return found;
    };
    if (!other) other = pick(d.members || ch.members || d.users || ch.users);
    if (!other) other = pick(d.member_ids || d.user_ids || ch.member_ids || ch.user_ids);
    if (!other && (d.other_user_id !== undefined || d.user_id !== undefined)) {
      var oid = d.other_user_id !== undefined ? d.other_user_id : d.user_id;
      other = getUser(oid) || { id: oid };
    }
    if (other && other.id !== undefined) {
      if (other.username) other = cacheUser(other);
      else { var cached = getUser(other.id); if (cached) other = cached; else ensureUser(other.id); }
    }
    return {
      id: id, is_dm: true, name: ch.name || '', other: other, workspace_id: ch.workspace_id !== undefined ? ch.workspace_id : d.workspace_id,
      topic: ch.topic || '', is_archived: !!ch.is_archived, is_private: true, is_member: true
    };
  }
  function dmName(dm) {
    if (dm.other) {
      var u = dm.other.id !== undefined ? (getUser(dm.other.id) || dm.other) : dm.other;
      if (u.username || u.display_name) return userName(u);
    }
    var saved = null;
    try { saved = JSON.parse(lsGet('huddle.dmNames') || '{}')[key(dm.id)]; } catch (e) { saved = null; }
    if (saved) return saved;
    if (dm.other && S.me && sameId(dm.other.id, S.me.id)) return userName(S.me) + ' (you)';
    return dm.name || 'Direct message';
  }
  function rememberDmName(id, name) {
    var m = {};
    try { m = JSON.parse(lsGet('huddle.dmNames') || '{}') || {}; } catch (e) { m = {}; }
    m[key(id)] = name;
    lsSet('huddle.dmNames', JSON.stringify(m));
  }
  function setDms(list) {
    var prev = new Map(S.dms.map(function (d) { return [key(d.id), d]; }));
    var out = [];
    (list || []).forEach(function (raw) {
      var d = normalizeDm(raw);
      if (!d) return;
      if (d.workspace_id !== undefined && d.workspace_id !== null && S.ws && !sameId(d.workspace_id, S.ws.id)) return;
      var p = prev.get(key(d.id));
      if (p && !d.other && p.other) d.other = p.other;
      if (!out.some(function (x) { return sameId(x.id, d.id); })) out.push(d);
    });
    // keep locally-started DMs that the server list doesn't know about yet
    S.dms.forEach(function (d) { if (!out.some(function (x) { return sameId(x.id, d.id); }) && d.local) out.push(d); });
    S.dms = out;
    S.dms.forEach(function (d) { subscribe(d.id); });
    if (S.current && S.current.is_dm) {
      var cur = S.dms.find(function (d) { return sameId(d.id, S.current.id); });
      if (cur) S.current = cur;
    }
    renderDmList();
  }
  function loadDms(skip) {
    if (skip) return Promise.resolve();
    return api('GET', '/api/dms', null, { quiet: true }).then(function (d) {
      var list = d.dms || d.channels || d.conversations || [];
      if (Array.isArray(list)) setDms(list);
    }).catch(function () { /* endpoint optional */ });
  }
  function renderDmList() {
    var ul = byId('dms-list');
    clear(ul);
    if (!S.dms.length) {
      ul.appendChild(el('li', { class: 'sidebar-empty' }, 'No direct messages yet'));
      return;
    }
    S.dms.slice().sort(function (a, b) { return dmName(a).localeCompare(dmName(b)); }).forEach(function (d) {
      var k = key(d.id);
      var active = S.current && S.current.is_dm && sameId(S.current.id, d.id);
      var unread = !active && S.unread[k] > 0 ? S.unread[k] : 0;
      var name = dmName(d);
      ul.appendChild(el('li', null, el('button', {
        type: 'button', class: 'dm-entry' + (active ? ' active' : '') + (unread ? ' unread' : ''), 'data-testid': 'dm-entry',
        'data-channel-id': d.id, 'data-dm-user': d.other && d.other.username ? d.other.username : null,
        'aria-current': active ? 'page' : null, title: 'Direct message with ' + name,
        onclick: function () { selectChannel(d); }
      }, [
        avatarEl(d.other || { display_name: name }, d.other ? d.other.id : d.id, 'tiny'),
        el('span', { class: 'channel-entry-name' }, name),
        unread ? el('span', { class: 'unread-badge' }, String(unread)) : null
      ])));
    });
  }
  function findMemberByUsername(username) {
    var u = username.replace(/^@/, '').toLowerCase();
    var m = S.members.find(function (x) { var usr = x.user || getUser(x.user_id); return usr && String(usr.username).toLowerCase() === u; });
    if (m) return m.user || getUser(m.user_id);
    var found = null;
    S.users.forEach(function (usr) { if (!found && usr && String(usr.username).toLowerCase() === u) found = usr; });
    return found;
  }
  function onStartDm(e) {
    e.preventDefault();
    var input = byId('dm-start-input');
    var username = input.value.trim().replace(/^@/, '');
    setError('dm-start-error', null);
    if (!username) return setError('dm-start-error', 'Enter a username.');
    var go = function () {
      var u = findMemberByUsername(username);
      if (!u) { setError('dm-start-error', 'No member named @' + username + ' in this workspace.'); return null; }
      return api('POST', '/api/dms', { user_id: u.id }, { quiet: true }).then(function (r) {
        var cid = r.channel_id !== undefined ? r.channel_id : (r.channel ? r.channel.id : (r.dm ? (r.dm.channel_id || r.dm.id) : undefined));
        if (cid === undefined) throw ApiError(0, 'Unexpected response from server.');
        rememberDmName(cid, userName(u));
        var dm = S.dms.find(function (x) { return sameId(x.id, cid); });
        if (!dm) {
          dm = { id: cid, is_dm: true, other: u, name: '', topic: '', is_archived: false, is_private: true, is_member: true, local: true };
          S.dms.push(dm);
        } else if (!dm.other) dm.other = u;
        subscribe(cid);
        input.value = '';
        show('dm-start-form', false);
        renderDmList();
        return selectChannel(dm);
      }).catch(function (err) { setError('dm-start-error', err.message); });
    };
    if (!findMemberByUsername(username)) loadMembers().then(go); else go();
  }

  // ------------------------------------------------------------------ channel selection
  function selectChannel(ch) {
    if (!ch) return Promise.resolve();
    var joinFirst = (ch.is_member === false && !ch.is_dm) ? joinChannel(ch) : Promise.resolve(true);
    return joinFirst.then(function (ok) {
      if (!ok) return;
      closeEmojiPicker();
      if (!S.current || !sameId(S.current.id, ch.id)) closeThreadPanel();
      S.current = ch;
      S.editingId = null;
      S.unread[key(ch.id)] = 0;
      if (S.ws) lsSet('huddle.lastChannel.' + S.ws.slug, key(ch.id));
      renderChannelList();
      renderDmList();
      renderHeader();
      renderComposerState();
      setError('composer-error', null);
      subscribe(ch.id);
      return loadMessages(ch);
    });
  }

  function joinChannel(ch) {
    return api('POST', '/api/channels/' + encodeURIComponent(ch.id) + '/join', {}).then(function (r) {
      if (r && r.channel) Object.assign(ch, r.channel);
      ch.is_member = true;
      subscribe(ch.id);
      return true;
    }, function () { return false; });
  }

  function loadMessages(ch) {
    var token = ++S.loadSeq;
    var list = byId('message-list');
    S.messages = new Map();
    S.order = [];
    S.hasMore = false;
    clear(list);
    list.appendChild(el('div', { class: 'list-status' }, 'Loading messages…'));
    var path = '/api/channels/' + encodeURIComponent(ch.id) + '/messages?limit=50';
    return api('GET', path, null, { quiet: true }).catch(function (err) {
      if (err.status === 403 && !ch.is_dm && !ch.is_private) {
        return joinChannel(ch).then(function (ok) { if (!ok) throw err; return api('GET', path, null, { quiet: true }); });
      }
      throw err;
    }).then(function (d) {
      if (token !== S.loadSeq) return;
      var msgs = (d.messages || []).slice();
      S.hasMore = msgs.length >= 50;
      msgs.reverse().forEach(function (m) { storeMessage(m); });
      renderAllMessages(true);
      markRead();
      if (!isTypingElsewhere()) byId('message-input').focus();
    }).catch(function (err) {
      if (token !== S.loadSeq) return;
      clear(list);
      list.appendChild(el('div', { class: 'list-status' }, 'Could not load messages: ' + err.message));
      toast(err.message, 'error');
    });
  }

  function isTypingElsewhere() {
    var a = document.activeElement;
    return a && a !== document.body && (a.tagName === 'INPUT' || a.tagName === 'TEXTAREA' || a.tagName === 'SELECT') && a.id !== 'message-input';
  }

  function loadOlder() {
    if (!S.current || !S.hasMore || S.loadingOlder || !S.order.length) return;
    S.loadingOlder = true;
    var ch = S.current;
    var token = S.loadSeq;
    var oldest = S.order[0];
    var list = byId('message-list');
    var prevHeight = list.scrollHeight;
    api('GET', '/api/channels/' + encodeURIComponent(ch.id) + '/messages?limit=50&before=' + encodeURIComponent(oldest), null, { quiet: true })
      .then(function (d) {
        if (token !== S.loadSeq) return;
        var msgs = d.messages || [];
        S.hasMore = msgs.length >= 50;
        var older = [];
        msgs.slice().reverse().forEach(function (m) {
          if (!isVisibleTopLevel(m) || S.messages.has(key(m.id))) return;
          S.messages.set(key(m.id), m);
          older.push(key(m.id));
        });
        S.order = older.concat(S.order);
        renderAllMessages(false);
        list.scrollTop = list.scrollHeight - prevHeight;
      })
      .catch(function () { /* ignore */ })
      .then(function () { S.loadingOlder = false; });
  }

  // ------------------------------------------------------------------ header & composer
  function renderHeader() {
    var ch = S.current;
    var title = byId('channel-title');
    var topic = byId('channel-topic');
    if (!ch) {
      title.textContent = S.ws ? S.ws.name : '';
      topic.textContent = '';
      topic.classList.add('is-empty');
      renderWorkspaceHeader();
      return;
    }
    if (ch.is_dm) {
      title.textContent = dmName(ch);
      title.title = 'Direct message with ' + dmName(ch);
    } else {
      title.textContent = (ch.is_private ? '🔒 ' : '# ') + ch.name;
      title.title = (ch.is_private ? 'Private channel #' : '#') + ch.name + (ch.is_archived ? ' (archived)' : '');
    }
    if (ch.topic) {
      topic.textContent = ch.topic;
      topic.title = ch.topic;
      topic.classList.remove('is-empty');
    } else {
      topic.textContent = 'Add a topic';
      topic.title = 'Click to add a topic';
      topic.classList.add('is-empty');
    }
    title.setAttribute('data-channel-id', key(ch.id));
    var ph = ch.is_dm ? 'Message ' + dmName(ch) : 'Message #' + ch.name;
    byId('message-input').setAttribute('placeholder', ph);
    renderWorkspaceHeader();
  }

  function renderComposerState() {
    var archived = !!(S.current && S.current.is_archived);
    show('composer', !archived);
    show('archived-notice', archived);
    var unarch = byId('archived-unarchive-btn');
    if (unarch) unarch.hidden = !(S.myRole === 'owner' || (S.ws && S.me && sameId(S.ws.owner_id, S.me.id)));
    document.querySelector('.composer-footer').hidden = archived;
    if (archived) closeEmojiPicker();
  }

  function autosize(ta) {
    ta.style.height = 'auto';
    ta.style.height = Math.min(ta.scrollHeight, 200) + 'px';
  }

  function updateSendState(ta, btn) {
    btn.classList.toggle('is-empty', !ta.value.trim());
  }

  function sendMessage() {
    var ta = byId('message-input');
    var body = ta.value;
    if (!S.current) return;
    if (!body.trim()) {
      setError('composer-error', "You can't send an empty message. Type something first.");
      ta.focus();
      return;
    }
    setError('composer-error', null);
    if (S.sending) return;
    S.sending = true;
    var ch = S.current;
    api('POST', '/api/channels/' + encodeURIComponent(ch.id) + '/messages', { body: body }, { quiet: true }).then(function (r) {
      if (ta.value === body) ta.value = '';
      autosize(ta);
      updateSendState(ta, byId('send-btn'));
      handlePostResult(r, ch);
    }).catch(function (err) {
      var msg = err.status === 423 ? 'This channel is archived — messages are read-only.' : err.message;
      setError('composer-error', msg);
      toast(msg, 'error');
      if (err.status === 423 && S.current === ch) { ch.is_archived = true; renderComposerState(); renderChannelList(); }
    }).then(function () { S.sending = false; });
  }

  function handlePostResult(r, ch) {
    if (!r) return;
    if (r.message) {
      if (r.message.parent_id) addReply(r.message, null);
      else if (S.current && sameId(r.message.channel_id !== undefined ? r.message.channel_id : ch.id, S.current.id)) upsertMessage(r.message, true);
    }
    if (r.channel) applyChannelUpdate(r.channel);
    if (r.invited_user) toast('Added @' + (r.invited_user.username || userName(r.invited_user)) + ' to ' + channelLabel(ch), 'success');
    else if (!r.message && r.channel) toast('Channel updated', 'success');
  }

  // ------------------------------------------------------------------ messages: store & render
  function isVisibleTopLevel(m) {
    return m && !m.parent_id && !m.deleted_at && !m.is_deleted && !m.deleted;
  }

  function storeMessage(m) {
    if (!isVisibleTopLevel(m)) return;
    var k = key(m.id);
    if (!S.messages.has(k)) S.order.push(k);
    S.messages.set(k, m);
    authorOf(m);
  }

  function sortOrder() {
    S.order.sort(function (a, b) {
      var ma = S.messages.get(a), mb = S.messages.get(b);
      var ta = parseDate(ma.created_at), tb = parseDate(mb.created_at);
      var da = ta ? ta.getTime() : 0, db = tb ? tb.getTime() : 0;
      if (da !== db) return da - db;
      return Number(a) - Number(b);
    });
  }

  function emptyStateEl() {
    var ch = S.current;
    if (!ch) return el('div', { class: 'channel-empty-state', 'data-testid': 'channel-empty-state' }, [el('h3', null, 'No channel selected'), el('p', null, 'Pick a channel from the sidebar or create a new one.')]);
    if (ch.is_dm) {
      return el('div', { class: 'channel-empty-state', 'data-testid': 'channel-empty-state' }, [
        el('div', { class: 'empty-icon' }, '@'),
        el('h3', null, 'This is the very beginning of your conversation with ' + dmName(ch) + '.'),
        el('p', null, 'Direct messages are private between the two of you. Send a message to get started.')
      ]);
    }
    return el('div', { class: 'channel-empty-state', 'data-testid': 'channel-empty-state' }, [
      el('div', { class: 'empty-icon' }, ch.is_private ? '🔒' : '#'),
      el('h3', null, 'This is the very beginning of #' + ch.name + '.'),
      el('p', null, (ch.topic ? 'Topic: ' + ch.topic + '. ' : '') + 'No messages yet — send a message to get the conversation started.')
    ]);
  }

  function renderEmptyNoChannel() {
    var list = byId('message-list');
    clear(list);
    list.appendChild(emptyStateEl());
  }

  function renderAllMessages(scrollToBottom) {
    var list = byId('message-list');
    var editing = S.editingId ? list.querySelector('.message[data-message-id="' + S.editingId + '"] .message-editor') : null;
    clear(list);
    sortOrder();
    if (!S.order.length) {
      list.appendChild(emptyStateEl());
      return;
    }
    if (S.hasMore) {
      list.appendChild(el('button', { type: 'button', class: 'btn btn-small btn-outline load-older', onclick: loadOlder }, 'Load older messages'));
    } else if (S.current && !S.current.is_dm) {
      list.appendChild(el('div', { class: 'channel-beginning' }, [el('strong', null, 'This is the very beginning of #' + S.current.name + '.'), ' ', S.current.topic ? 'Topic: ' + S.current.topic : '']));
    }
    var lastDay = null;
    S.order.forEach(function (k, i) {
      var m = S.messages.get(k);
      var d = dayKey(m.created_at);
      if (d !== lastDay) {
        list.appendChild(el('div', { class: 'day-divider', role: 'separator' }, fmtDay(m.created_at)));
        lastDay = d;
      }
      var row = renderMessageRow(m);
      if (i === 0) row.classList.add('first-row');
      list.appendChild(row);
    });
    if (editing && S.editingId) {
      var r = list.querySelector('.message[data-message-id="' + S.editingId + '"]');
      if (r) attachEditor(r, editing);
    }
    if (scrollToBottom) list.scrollTop = list.scrollHeight;
  }

  function nearBottom(list) { return list.scrollHeight - list.scrollTop - list.clientHeight < 140; }

  function upsertMessage(m, forceScroll) {
    if (!S.current) return;
    if (!isVisibleTopLevel(m)) {
      if (m && (m.deleted_at || m.is_deleted || m.deleted)) removeMessage(m.id);
      return;
    }
    var k = key(m.id);
    var list = byId('message-list');
    var existing = S.messages.get(k);
    if (existing) {
      // keep the larger reply count (events may race)
      if (existing.reply_count && (m.reply_count === undefined || m.reply_count < existing.reply_count) && !m.__authoritative) m.reply_count = existing.reply_count;
      S.messages.set(k, m);
      authorOf(m);
      var old = list.querySelector('.message[data-message-id="' + k + '"]');
      if (old) {
        var row = renderMessageRow(m);
        if (old.classList.contains('first-row')) row.classList.add('first-row');
        var ed = S.editingId === k ? old.querySelector('.message-editor') : null;
        var wasActive = old.classList.contains('is-active');
        old.parentNode.replaceChild(row, old);
        if (wasActive) row.classList.add('is-active');
        if (ed) attachEditor(row, ed);
        if (S.picker && S.picker.messageId === k) {
          var rb = row.querySelector('[data-testid="reaction-button"]');
          if (rb) S.picker.anchor = rb;
        }
      }
      if (S.thread && sameId(S.thread.parentId, m.id)) { S.thread.parent = m; renderThreadParent(); }
      return;
    }
    var stick = forceScroll || nearBottom(list);
    storeMessage(m);
    var lastK = S.order.length > 1 ? S.order[S.order.length - 2] : null;
    var last = lastK ? S.messages.get(lastK) : null;
    var inOrder = !last || (parseDate(last.created_at) || 0) <= (parseDate(m.created_at) || 0);
    if (S.order.length === 1 || !inOrder) {
      renderAllMessages(stick);
      return;
    }
    if (dayKey(last.created_at) !== dayKey(m.created_at)) list.appendChild(el('div', { class: 'day-divider', role: 'separator' }, fmtDay(m.created_at)));
    list.appendChild(renderMessageRow(m));
    if (stick) list.scrollTop = list.scrollHeight;
  }

  function removeMessage(id) {
    var k = key(id);
    if (S.thread && sameId(S.thread.parentId, id)) closeThreadPanel();
    if (S.thread) {
      var before = S.thread.replies.length;
      S.thread.replies = S.thread.replies.filter(function (r) { return !sameId(r.id, id); });
      if (S.thread.replies.length !== before) renderThread();
    }
    if (!S.messages.has(k)) return;
    S.messages.delete(k);
    S.order = S.order.filter(function (x) { return x !== k; });
    if (S.editingId === k) S.editingId = null;
    if (S.picker && S.picker.messageId === k) closeEmojiPicker();
    renderAllMessages(false);
  }

  function findMessage(id) {
    var m = S.messages.get(key(id));
    if (m) return m;
    if (S.thread) {
      if (sameId(S.thread.parentId, id)) return S.thread.parent;
      return S.thread.replies.find(function (r) { return sameId(r.id, id); }) || null;
    }
    return null;
  }

  function renderBody(text, container) {
    var re = /(https?:\/\/[^\s<>"']+[^\s<>"'.,;:!?)\]])|(@[A-Za-z0-9_][A-Za-z0-9_.-]*[A-Za-z0-9_]|@[A-Za-z0-9_])/g;
    var last = 0, m;
    var myName = S.me ? String(S.me.username).toLowerCase() : null;
    while ((m = re.exec(text)) !== null) {
      if (m.index > last) container.appendChild(document.createTextNode(text.slice(last, m.index)));
      if (m[1]) {
        container.appendChild(el('a', { href: m[1], target: '_blank', rel: 'noopener noreferrer' }, m[1]));
      } else {
        var prevCh = m.index > 0 ? text.charAt(m.index - 1) : ' ';
        if (/[A-Za-z0-9_.]/.test(prevCh)) container.appendChild(document.createTextNode(m[0]));
        else {
          var handle = m[0].slice(1).toLowerCase();
          var isMe = handle === myName || handle === 'channel' || handle === 'here';
          container.appendChild(el('span', { class: 'mention' + (isMe ? ' mention-me' : '') }, m[0]));
        }
      }
      last = re.lastIndex;
    }
    if (last < text.length) container.appendChild(document.createTextNode(text.slice(last)));
  }

  function bodyEl(m, testid) {
    var body = String(m.body || '');
    var isMe = /^\/me\s+\S/.test(body);
    var b = el('span', { class: 'message-body' + (isMe ? ' me-action' : ''), 'data-testid': testid || 'message-body' });
    if (isMe) {
      var author = authorOf(m);
      b.appendChild(el('em', null, (author ? userName(author) : '') + ' ' + body.replace(/^\/me\s+/, '')));
    } else {
      renderBody(body, b);
    }
    return b;
  }

  function filesEl(m) {
    var files = Array.isArray(m.files) ? m.files : [];
    if (!files.length) return null;
    return el('div', { class: 'message-files' }, files.map(function (f) {
      return el('a', { class: 'file-chip', href: '/api/files/' + encodeURIComponent(f.id) + '/download', 'data-file-id': f.id,
        onclick: function (e) { e.preventDefault(); downloadFile(f); } },
      ['📎 ', f.filename || 'file', f.size ? el('span', { class: 'muted' }, ' · ' + humanSize(f.size)) : null]);
    }));
  }
  function humanSize(n) { n = Number(n) || 0; if (n < 1024) return n + ' B'; if (n < 1048576) return (n / 1024).toFixed(1) + ' KB'; return (n / 1048576).toFixed(1) + ' MB'; }
  function downloadFile(f) {
    fetch('/api/files/' + encodeURIComponent(f.id) + '/download', { headers: { Authorization: 'Bearer ' + S.token } })
      .then(function (r) { if (!r.ok) throw new Error('Download failed (' + r.status + ')'); return r.blob(); })
      .then(function (blob) {
        var url = URL.createObjectURL(blob);
        var a = el('a', { href: url, download: f.filename || 'file' });
        document.body.appendChild(a); a.click(); a.remove();
        setTimeout(function () { URL.revokeObjectURL(url); }, 2000);
      }).catch(function (e) { toast(e.message, 'error'); });
  }

  function reactionsEl(m, interactive) {
    var reactions = (Array.isArray(m.reactions) ? m.reactions : []).filter(function (r) { return r && Number(r.count || (r.user_ids || []).length) > 0; });
    var wrap = el('div', { class: 'reactions', 'data-testid': interactive ? 'reactions' : 'thread-reactions' });
    if (!reactions.length) { wrap.hidden = true; return wrap; }
    reactions.forEach(function (r) {
      var count = Number(r.count !== undefined ? r.count : (r.user_ids || []).length);
      var mine = S.me && (r.user_ids || []).some(function (u) { return sameId(u, S.me.id); });
      var names = (r.user_ids || []).map(function (u) { var usr = getUser(u); return usr ? userName(usr) : null; }).filter(Boolean);
      wrap.appendChild(el('button', {
        type: 'button', class: 'reaction-chip' + (mine ? ' mine' : ''), 'data-testid': interactive ? 'reaction-chip' : 'thread-reaction-chip',
