        title: (names.length ? names.join(', ') : count + (count === 1 ? ' person' : ' people')) + ' reacted with ' + r.emoji + (mine ? ' (click to remove yours)' : ' (click to add yours)'),
        onclick: function (e) { e.stopPropagation(); toggleReaction(m.id, r.emoji); }
      }, [el('span', { class: 'reaction-emoji' }, r.emoji), el('span', { class: 'reaction-count', 'data-testid': 'reaction-count' }, String(count))]));
    });
    return wrap;
  }

  function replyLinkText(n) { return n + (n === 1 ? ' reply' : ' replies'); }

  function renderMessageRow(m) {
    var k = key(m.id);
    var author = authorOf(m);
    var mine = S.me && sameId(m.author_id !== undefined ? m.author_id : (m.author && m.author.id), S.me.id);
    var replies = Number(m.reply_count || 0);
    var row = el('div', {
