    row.appendChild(content);

    var tb = el('div', { class: 'message-toolbar', role: 'toolbar', 'aria-label': 'Message actions', 'data-testid': 'message-toolbar' });
    tb.appendChild(el('button', {
      type: 'button', class: 'toolbar-btn', 'data-testid': 'reaction-button', title: 'Add reaction', 'aria-label': 'Add reaction',
      onclick: function (e) { e.stopPropagation(); toggleEmojiPicker(e.currentTarget, k); }
    }, [el('span', { 'aria-hidden': 'true' }, '😀'), el('span', { class: 'tb-label' }, '+')]));
    tb.appendChild(el('button', {
      type: 'button', class: 'toolbar-btn', 'data-testid': 'open-thread-btn', title: 'Reply in thread', 'aria-label': 'Reply in thread',
      onclick: function (e) { e.stopPropagation(); openThread(m.id); }
    }, [el('span', { 'aria-hidden': 'true' }, '💬'), el('span', { class: 'tb-label' }, 'Reply')]));
    if (mine) {
      tb.appendChild(el('button', {
        type: 'button', class: 'toolbar-btn', 'data-testid': 'edit-message-btn', title: 'Edit message', 'aria-label': 'Edit message',
        onclick: function (e) { e.stopPropagation(); startEdit(k); }
      }, [el('span', { 'aria-hidden': 'true' }, '✏️'), el('span', { class: 'tb-label' }, 'Edit')]));
    }
    if (mine || S.myRole === 'owner') {
      tb.appendChild(el('button', {
        type: 'button', class: 'toolbar-btn danger', 'data-testid': 'delete-message-btn', title: 'Delete message', 'aria-label': 'Delete message',
        onclick: function (e) { e.stopPropagation(); deleteMessage(k); }
      }, [el('span', { 'aria-hidden': 'true' }, '🗑️'), el('span', { class: 'tb-label' }, 'Delete')]));
    }
    row.appendChild(tb);
    return row;
  }

  // ------------------------------------------------------------------ edit / delete
  function startEdit(k) {
    var m = S.messages.get(key(k));
    if (!m) return;
    if (S.editingId && S.editingId !== key(k)) cancelEdit();
    S.editingId = key(k);
    var row = byId('message-list').querySelector('.message[data-message-id="' + key(k) + '"]');
    if (!row) return;
    var ta = el('textarea', { class: 'edit-message-input', 'data-testid': 'edit-message-input', name: 'body', rows: '2', 'aria-label': 'Edit message' });
    ta.value = m.body || '';
    var err = el('span', { class: 'inline-error', role: 'alert', 'data-testid': 'edit-message-error', hidden: true });
    var editor = el('form', { class: 'message-editor', 'data-testid': 'edit-message-form', novalidate: true,
      onsubmit: function (e) { e.preventDefault(); saveEdit(key(k), ta.value, err); } }, [
      ta,
      el('div', { class: 'message-editor-actions' }, [
        el('span', { class: 'hint' }, 'Enter to save · Esc to cancel'),
        err,
        el('button', { type: 'button', class: 'btn btn-small btn-secondary', 'data-testid': 'edit-message-cancel', onclick: function () { cancelEdit(); } }, 'Cancel'),
        el('button', { type: 'submit', class: 'btn btn-small btn-primary', 'data-testid': 'edit-message-save' }, 'Save')
      ])
    ]);
    ta.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) { e.preventDefault(); saveEdit(key(k), ta.value, err); }
      else if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); cancelEdit(); }
    });
    attachEditor(row, editor);
    ta.focus();
    ta.setSelectionRange(ta.value.length, ta.value.length);
  }
  function attachEditor(row, editor) {
    var text = row.querySelector('.message-text');
    if (text) { text.hidden = true; text.parentNode.insertBefore(editor, text.nextSibling); }
    row.classList.add('is-editing');
    var ta = editor.querySelector('textarea');
    if (ta && document.activeElement !== ta) setTimeout(function () { ta.focus(); }, 0);
  }
  function cancelEdit() {
    var k = S.editingId;
    S.editingId = null;
    if (!k) return;
    var row = byId('message-list').querySelector('.message[data-message-id="' + k + '"]');
    if (!row) return;
    var ed = row.querySelector('.message-editor');
    if (ed) ed.remove();
    var text = row.querySelector('.message-text');
    if (text) text.hidden = false;
    row.classList.remove('is-editing');
    row.focus();
  }
  function saveEdit(k, value, errEl) {
    var m = S.messages.get(k);
    if (!m) { cancelEdit(); return; }
    if (!value.trim()) {
      if (errEl) { errEl.textContent = "Message can't be empty — use Delete to remove it."; errEl.hidden = false; }
      return;
    }
    if (value === m.body) { cancelEdit(); return; }
    api('PATCH', '/api/messages/' + encodeURIComponent(m.id), { body: value }, { quiet: true }).then(function (r) {
      var updated = r.message || Object.assign({}, m, { body: value, edited_at: new Date().toISOString() });
      if (!updated.edited_at) updated.edited_at = new Date().toISOString();
      S.editingId = null;
      upsertMessage(updated);
      var row = byId('message-list').querySelector('.message[data-message-id="' + k + '"]');
      if (row) row.focus();
    }).catch(function (err) {
      if (errEl) { errEl.textContent = err.message; errEl.hidden = false; }
      toast(err.message, 'error');
    });
  }
  function deleteMessage(k) {
    var m = findMessage(k);
    if (!m) return;
    api('DELETE', '/api/messages/' + encodeURIComponent(m.id)).then(function () {
      removeMessage(m.id);
      toast('Message deleted', 'success');
    }).catch(function () { /* toast shown */ });
  }

  // ------------------------------------------------------------------ reactions
  function setReactions(messageId, reactions) {
    var m = S.messages.get(key(messageId));
    if (m) {
      var copy = Object.assign({}, m, { reactions: reactions });
      copy.__authoritative = false;
      upsertMessage(copy);
    }
    if (S.thread) {
      var changed = false;
      if (sameId(S.thread.parentId, messageId)) { S.thread.parent = Object.assign({}, S.thread.parent, { reactions: reactions }); changed = true; }
      S.thread.replies = S.thread.replies.map(function (r) {
        if (sameId(r.id, messageId)) { changed = true; return Object.assign({}, r, { reactions: reactions }); }
        return r;
      });
      if (changed) renderThread();
    }
  }
  function toggleReaction(messageId, emoji) {
    var m = findMessage(messageId);
    var existing = m && (m.reactions || []).find(function (r) { return r.emoji === emoji; });
    var mine = existing && S.me && (existing.user_ids || []).some(function (u) { return sameId(u, S.me.id); });
    var p = mine
      ? api('DELETE', '/api/messages/' + encodeURIComponent(messageId) + '/reactions/' + encodeURIComponent(emoji))
      : api('POST', '/api/messages/' + encodeURIComponent(messageId) + '/reactions', { emoji: emoji });
    return p.then(function (r) { if (r && Array.isArray(r.reactions)) setReactions(messageId, r.reactions); }).catch(function () { /* toast shown */ });
  }

  // ------------------------------------------------------------------ emoji picker
  function toggleEmojiPicker(anchor, messageId) {
    if (S.picker && S.picker.messageId === key(messageId)) { closeEmojiPicker(); return; }
    openEmojiPicker(anchor, messageId);
  }
  function openEmojiPicker(anchor, messageId) {
    closeEmojiPicker();
    var k = key(messageId);
    var picker = el('div', { class: 'emoji-picker', 'data-testid': 'emoji-picker', role: 'dialog', 'aria-label': 'Choose a reaction' });
    picker.appendChild(el('div', { class: 'emoji-picker-title' }, 'Add a reaction'));
    var grid = el('div', { class: 'emoji-grid', role: 'listbox' });
    EMOJIS.forEach(function (emoji) {
      grid.appendChild(el('button', {
        type: 'button', class: 'emoji-option', 'data-testid': 'emoji-option', 'data-emoji': emoji, role: 'option',
        title: 'React with ' + emoji, 'aria-label': 'React with ' + emoji,
        onclick: function (e) {
          e.stopPropagation();
          closeEmojiPicker();
          var m = findMessage(k);
          var already = m && (m.reactions || []).some(function (r) { return r.emoji === emoji && S.me && (r.user_ids || []).some(function (u) { return sameId(u, S.me.id); }); });
          if (already) return;
          toggleReaction(k, emoji);
        }
      }, emoji));
    });
    picker.appendChild(grid);
    picker.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { e.preventDefault(); closeEmojiPicker(); if (anchor && anchor.isConnected) anchor.focus(); }
    });
    document.body.appendChild(picker);
    var row = anchor.closest ? anchor.closest('.message, .thread-msg') : null;
    if (row) row.classList.add('is-active');
    S.picker = { el: picker, anchor: anchor, messageId: k, row: row };
    positionPicker();
    var first = picker.querySelector('.emoji-option');
    if (first) first.focus({ preventScroll: true });
  }
  function positionPicker() {
    if (!S.picker) return;
    var p = S.picker.el, a = S.picker.anchor;
    if (!a || !a.isConnected) {
      var row = document.querySelector('.message[data-message-id="' + S.picker.messageId + '"] [data-testid="reaction-button"]');
      if (row) a = S.picker.anchor = row;
    }
    var rect = a && a.isConnected ? a.getBoundingClientRect() : { top: 100, bottom: 120, left: 300, right: 340 };
    var w = p.offsetWidth || 296, h = p.offsetHeight || 200;
    var top = rect.bottom + 6;
    if (top + h > window.innerHeight - 8) top = Math.max(8, rect.top - h - 6);
    var left = rect.right - w;
    left = Math.max(8, Math.min(left, window.innerWidth - w - 8));
    p.style.top = top + 'px';
    p.style.left = left + 'px';
  }
  function closeEmojiPicker() {
    if (!S.picker) return;
    if (S.picker.el.parentNode) S.picker.el.parentNode.removeChild(S.picker.el);
    if (S.picker.row) S.picker.row.classList.remove('is-active');
    document.querySelectorAll('.message.is-active').forEach(function (r) { r.classList.remove('is-active'); });
    S.picker = null;
  }

  // ------------------------------------------------------------------ threads
  function openThread(messageId) {
    var parent = S.messages.get(key(messageId));
    if (!parent) return;
    closeEmojiPicker();
    var k = key(messageId);
    S.thread = { parentId: k, parent: parent, replies: [], loading: true };
    show('thread-panel', true);
    byId('app').classList.add('thread-open');
    byId('thread-channel-name').textContent = S.current ? channelLabel(S.current) : '';
    setError('thread-error', null);
    renderThread();
    var ta = byId('thread-input');
    ta.value = '';
    autosize(ta);
    updateSendState(ta, byId('thread-send'));
    ta.focus();
    api('GET', '/api/messages/' + encodeURIComponent(parent.id) + '/replies', null, { quiet: true }).then(function (d) {
      if (!S.thread || S.thread.parentId !== k) return;
      var replies = (d.replies || d.messages || []).filter(function (r) { return !r.deleted_at && !r.is_deleted; });
      var existing = S.thread.replies;
      S.thread.replies = replies;
      existing.forEach(function (r) { if (!replies.some(function (x) { return sameId(x.id, r.id); })) S.thread.replies.push(r); });
      S.thread.replies.forEach(function (r) { S.seenReplies.add(key(r.id)); authorOf(r); });
      S.thread.loading = false;
      syncReplyCount(S.thread.replies.length, true);
      renderThread();
      var sc = byId('thread-scroll');
      sc.scrollTop = sc.scrollHeight;
    }).catch(function (err) {
      if (!S.thread || S.thread.parentId !== k) return;
      S.thread.loading = false;
      renderThread();
      setError('thread-error', 'Could not load replies: ' + err.message);
    });
  }
  function closeThreadPanel() {
    S.thread = null;
    show('thread-panel', false);
    var app = byId('app');
    if (app) app.classList.remove('thread-open');
  }
  function syncReplyCount(n, onlyIncrease) {
    if (!S.thread) return;
    var m = S.messages.get(S.thread.parentId);
    if (!m) return;
    var cur = Number(m.reply_count || 0);
    if (onlyIncrease ? n > cur : n !== cur) {
      var copy = Object.assign({}, m, { reply_count: n, __authoritative: true });
      upsertMessage(copy);
      delete copy.__authoritative;
    }
  }
  function threadRow(m, isParent) {
    var author = authorOf(m);
    var mine = S.me && sameId(m.author_id, S.me.id);
    var row = el('div', {
      class: 'thread-msg' + (isParent ? ' thread-parent-msg' : ''), 'data-testid': isParent ? 'thread-parent-message' : 'thread-reply',
      'data-message-id': key(m.id), 'data-author-id': key(m.author_id)
    });
    row.appendChild(avatarEl(author, m.author_id));
    var content = el('div', { class: 'message-content' });
