    authorOf(reply);
    var parent = S.messages.get(key(pid));
    if (parent) {
      var cur = Number(parent.reply_count || 0);
      var next = replyCount !== null && replyCount !== undefined ? Number(replyCount) : (isNew ? cur + 1 : cur);
      if (S.thread && sameId(S.thread.parentId, pid)) {
        var inThread = S.thread.replies.some(function (r) { return sameId(r.id, reply.id); });
        next = Math.max(next, S.thread.replies.length + (inThread ? 0 : 1));
      }
      if (next !== cur) {
