  // ------------------------------------------------------------------ WebSocket
  function setConn(online) {
    var n = byId('connection-status');
    if (!n) return;
    n.classList.toggle('offline', !online);
    n.textContent = online ? '● Live' : '● Reconnecting…';
    n.title = online ? 'Connected for live updates' : 'Live updates paused — reconnecting';
  }
  function wsSend(obj) {
    if (S.socket && S.socketOpen) {
      try { S.socket.send(JSON.stringify(obj)); return true; } catch (e) { return false; }
    }
    return false;
  }
  function subscribe(id) {
    if (id === undefined || id === null) return;
    var k = key(id);
    if (S.subs.has(k)) return;
    S.subs.set(k, id);
    sendSub(id);
  }
  function sendSub(id) {
    var k = key(id);
    var cid = typeof id === 'string' && /^\d+$/.test(id) ? Number(id) : id;
    if (S.lastSeq[k] !== undefined) wsSend({ type: 'resume', channel_id: cid, since_seq: S.lastSeq[k] });
    else wsSend({ type: 'subscribe', channel_id: cid });
  }
  function connectWS() {
    if (!S.token) return;
    clearTimeout(S.wsTimer);
    if (S.socket) { var old = S.socket; S.socket = null; try { old.close(); } catch (e) { /* ignore */ } }
    var url = (location.protocol === 'https:' ? 'wss' : 'ws') + '://' + location.host + '/api/ws?token=' + encodeURIComponent(S.token);
    var sock;
    try { sock = new WebSocket(url); } catch (e) { scheduleReconnect(); return; }
    S.socket = sock;
    S.socketOpen = false;
    sock.onopen = function () {
      if (S.socket !== sock) return;
      S.socketOpen = true;
      S.wsBackoff = 500;
      setConn(true);
      S.subs.forEach(function (id) { sendSub(id); });
      clearInterval(S.pingTimer);
      S.pingTimer = setInterval(function () { wsSend({ type: 'ping' }); }, 25000);
    };
    sock.onmessage = function (ev) {
      if (S.socket !== sock) return;
      var f;
      try { f = JSON.parse(ev.data); } catch (e) { return; }
      try { handleFrame(f); } catch (e) { if (window.console) console.error('frame handling failed', e, f); }
    };
    sock.onclose = function () {
      if (S.socket !== sock) return;
      S.socket = null;
      S.socketOpen = false;
      clearInterval(S.pingTimer);
      if (S.token) { setConn(false); scheduleReconnect(); }
    };
    sock.onerror = function () { /* onclose follows */ };
  }
  function scheduleReconnect() {
    if (!S.token) return;
    clearTimeout(S.wsTimer);
    var delay = S.wsBackoff;
    S.wsBackoff = Math.min(S.wsBackoff * 2, 5000);
    S.wsTimer = setTimeout(connectWS, delay);
  }

  function handleFrame(f) {
    if (!f || typeof f !== 'object') return;
    var t = f.type;
    var ck = f.channel_id !== undefined && f.channel_id !== null ? key(f.channel_id) : null;
    if (t === 'subscribed' || t === 'resumed') {
      if (ck && f.head_seq !== undefined && (S.lastSeq[ck] === undefined || (t === 'subscribed' && S.lastSeq[ck] < f.head_seq && !S.subsSeen))) {
        if (S.lastSeq[ck] === undefined) S.lastSeq[ck] = Number(f.head_seq);
      }
      if (S.current && ck === key(S.current.id)) markRead();
      return;
    }
    if (t === 'resume.gap') {
      if (ck) S.lastSeq[ck] = undefined;
      if (ck) { delete S.lastSeq[ck]; wsSend({ type: 'subscribe', channel_id: f.channel_id }); }
      if (S.current && ck === key(S.current.id)) loadMessages(S.current);
      return;
    }
    if (t === 'pong' || t === 'ping' || t === 'hello' || t === 'error') return;
    if (t === 'user.updated') {
      if (f.user) { cacheUser(f.user); refreshUserDisplay(f.user.id); }
      return;
    }
    if (ck && f.seq !== undefined && f.seq !== null) {
      var seq = Number(f.seq);
      if (S.lastSeq[ck] !== undefined && seq <= S.lastSeq[ck]) return; // duplicate / already seen
      S.lastSeq[ck] = seq;
    }
    var isCurrent = S.current && ck !== null && ck === key(S.current.id);
    var mineAuthor = function (m) { return m && S.me && sameId(m.author_id !== undefined ? m.author_id : (m.author && m.author.id), S.me.id); };
    switch (t) {
      case 'message.new':
      case 'message.created':
        if (!f.message) return;
        if (f.message.parent_id) { addReply(f.message, f.reply_count); return; }
        if (isCurrent) { upsertMessage(f.message, mineAuthor(f.message)); markRead(); }
        else if (!mineAuthor(f.message)) bumpUnread(ck);
        return;
      case 'message.reply':
        if (f.message) {
          if (!f.message.parent_id && f.parent_id !== undefined) f.message.parent_id = f.parent_id;
          addReply(f.message, f.reply_count);
        } else if (f.parent_id !== undefined && f.reply_count !== undefined) {
          var p = S.messages.get(key(f.parent_id));
          if (p) upsertMessage(Object.assign({}, p, { reply_count: f.reply_count }));
        }
        return;
      case 'message.updated':
      case 'message.edited':
        if (!f.message) return;
        if (f.message.parent_id) {
          if (S.thread && sameId(S.thread.parentId, f.message.parent_id)) addReply(f.message, null);
          return;
        }
        if (isCurrent && S.messages.has(key(f.message.id))) upsertMessage(f.message);
        return;
      case 'message.deleted':
        removeMessage(f.message_id !== undefined ? f.message_id : (f.message && f.message.id));
        return;
      case 'reaction.added':
      case 'reaction.removed':
        if (f.message_id !== undefined && Array.isArray(f.reactions)) setReactions(f.message_id, f.reactions);
        return;
      case 'pin.added':
      case 'pin.removed':
        return;
      case 'channel.updated':
      case 'channel.archived':
      case 'channel.unarchived':
        if (f.channel) {
          var c = Object.assign({}, f.channel);
          if (t === 'channel.archived') c.is_archived = true;
          if (t === 'channel.unarchived') c.is_archived = false;
          applyChannelUpdate(c);
        }
        return;
      case 'member.joined':
      case 'member.left':
        if (f.user) cacheUser(f.user);
        if (S.me && sameId(f.user_id, S.me.id)) {
          var ch = findChannel(f.channel_id);
          if (ch && !ch.is_dm) { ch.is_member = t === 'member.joined'; renderChannelList(); }
        }
        if (settingsChannel && !byId('channel-settings-modal').hidden && sameId(settingsChannel.id, f.channel_id)) loadChannelMembers();
        return;
      default:
        return;
    }
  }
  function bumpUnread(ck) {
    if (!ck) return;
    S.unread[ck] = (S.unread[ck] || 0) + 1;
    if (S.channels.some(function (c) { return key(c.id) === ck; })) renderChannelList();
    else if (S.dms.some(function (d) { return key(d.id) === ck; })) renderDmList();
    else loadDms(false);
  }

  // ------------------------------------------------------------------ bindings
  function bindComposer(taId, btnId, formId, send) {
    var ta = byId(taId), btn = byId(btnId), form = byId(formId);
    form.addEventListener('submit', function (e) { e.preventDefault(); send(); });
    ta.addEventListener('keydown', function (e) {
