    byId('channel-topic-form').addEventListener('submit', onChannelTopic);
    byId('channel-add-member-form').addEventListener('submit', onChannelAddMember);
    byId('archive-channel-btn').addEventListener('click', function () { setArchived(true); });
    byId('unarchive-channel-btn').addEventListener('click', function () { setArchived(false); });
    byId('archived-unarchive-btn').addEventListener('click', function () { settingsChannel = S.current; setArchived(false); });
