    showView('boot');
    api('GET', '/api/auth/me', null, { quiet: true, noAuthRedirect: true }).then(function (d) {
      return afterLogin(d.user || d);
    }).catch(function (err) {
      if (err && err.status === 401) {
        clearToken();
